import React, { useState, useEffect } from 'react';
import { UserProfile, ModuleId, ProjectData, DriveFile } from '../types';
import { MODULES } from '../constants';
import ActiveModule from './ActiveModule';
import Guide from './Guide';
import FAQ from './FAQ';
import Support from './Support';
import SaveProjectModal from './SaveProjectModal';
import Tooltip from './Tooltip';
import TourGuide from './TourGuide';
import { initDriveAuth, requestDriveToken, saveProjectToDrive, listProjectsFromDrive, loadProjectFromDrive, hasDriveToken } from '../services/googleDriveService';
import { useAutoSave } from '../hooks/useAutoSave';

interface DashboardProps {
  user: UserProfile;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, onLogout }) => {
  const [currentView, setCurrentView] = useState<string>('HOME');
  const [moduleHistory, setModuleHistory] = useState<Record<string, string[]>>({});
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  const [theme, setTheme] = useState<'dark' | 'light'>(() => {
    return (localStorage.getItem('obscura_theme') as 'dark' | 'light') || 'dark';
  });
  const [showSettings, setShowSettings] = useState(false);

  const [currentProject, setCurrentProject] = useState<ProjectData | null>(null);
  const [isDriveConnected, setIsDriveConnected] = useState(false);
  const [showSaveModal, setShowSaveModal] = useState(false);
  const [showLoadModal, setShowLoadModal] = useState(false);
  const [projectList, setProjectList] = useState<DriveFile[]>([]);
  const [autoSaveStatus, setAutoSaveStatus] = useState<'saved' | 'saving' | 'error' | 'idle'>('idle');
  const [isLoadingDrive, setIsLoadingDrive] = useState(false);

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
    localStorage.setItem('obscura_theme', theme);
  }, [theme]);

  useEffect(() => {
    const init = async () => {
      if (hasDriveToken()) setIsDriveConnected(true);
      try { await initDriveAuth(() => setIsDriveConnected(true)); } catch (e) {}
    };
    init();

    try {
      const stored = localStorage.getItem('obscura_module_history');
      if (stored) setModuleHistory(JSON.parse(stored));
    } catch (e) {}
  }, []);

  useEffect(() => {
    if (currentProject) {
      setCurrentProject(prev => prev ? { ...prev, moduleHistory } : null);
    }
  }, [moduleHistory]);

  useAutoSave(currentProject, isDriveConnected, setAutoSaveStatus);

  useEffect(() => {
    const mod = MODULES.find(m => m.id === currentView);
    document.title = mod ? `OBSCURA | ${mod.title}` : 'OBSCURA Studio';

    if (window.innerWidth < 768 && currentView !== 'HOME') setIsSidebarOpen(false);
  }, [currentView]);

  const handleModuleResult = (moduleId: ModuleId, result: string) => {
    setModuleHistory(prev => {
      const current = prev[moduleId] || [];
      const updated = { ...prev, [moduleId]: [...current, result] };
      localStorage.setItem('obscura_module_history', JSON.stringify(updated));
      return updated;
    });
  };

  const handleUpdateLastLog = (moduleId: ModuleId, updatedResult: string) => {
     setModuleHistory(prev => {
        const list = prev[moduleId] || [];
        if (list.length === 0) return prev;
        const newList = [...list];
        newList[newList.length - 1] = updatedResult;
        const updated = { ...prev, [moduleId]: newList };
        localStorage.setItem('obscura_module_history', JSON.stringify(updated));
        return updated;
     });
  };

  const handleCreateNewSave = async (name: string) => {
    setShowSaveModal(false);
    setIsLoadingDrive(true);
    try {
      const newProject: ProjectData = { name, lastModified: Date.now(), moduleHistory, version: '1.0' };
      const fileId = await saveProjectToDrive(newProject);
      setCurrentProject({ ...newProject, id: fileId });
      setAutoSaveStatus('saved');
    } catch (e) {
      alert("Save failed.");
    } finally {
      setIsLoadingDrive(false);
    }
  };

  const handleLoadList = async () => {
    setIsLoadingDrive(true);
    try {
        const files = await listProjectsFromDrive();
        setProjectList(files);
        setShowLoadModal(true);
    } catch (e) {
        alert("Drive access error.");
    } finally {
        setIsLoadingDrive(false);
    }
  };

  const handleClearCache = () => {
    if (confirm('Are you sure you want to clear the local analysis cache? This cannot be undone.')) {
      localStorage.removeItem('obscura_module_history');
      setModuleHistory({});
      alert('Local cache cleared.');
    }
  };

  const handleRestartTour = () => {
    localStorage.removeItem('obscura_tour_completed');
    window.location.reload();
  };

  const activeModule = MODULES.find(m => m.id === currentView);

  const cardStyle = `
    relative p-8 rounded-[2.5rem] transition-all duration-700 text-left group overflow-hidden
    bg-[var(--bg-card)] border border-[var(--border-subtle)] backdrop-blur-[2px]
    hover:border-[var(--accent)]/40 hover:shadow-[0_0_50px_var(--shadow-glow)]
  `;

  return (
    <div className="flex h-screen bg-[var(--bg-studio)] text-[var(--text-primary)] font-inter transition-all duration-500 overflow-hidden">
      <TourGuide />

      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 backdrop-blur-sm z-40 md:hidden animate-fade-in"
          onClick={() => setIsSidebarOpen(false)}
          aria-hidden="true"
        ></div>
      )}

      <aside 
        id="sidebar-nav"
        className={`
          fixed inset-y-0 left-0 z-50 w-72 bg-[var(--bg-sidebar)] border-r border-[var(--border-subtle)] flex flex-col transition-transform duration-500 ease-out
          ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} md:relative md:translate-x-0
        `}
        aria-label="Sidebar Navigation"
      >
        <div className="h-24 flex items-center px-8">
          <div 
            onClick={() => setCurrentView('HOME')} 
            className="cursor-pointer flex items-center gap-4 group"
            role="button"
            tabIndex={0}
            onKeyDown={(e) => e.key === 'Enter' && setCurrentView('HOME')}
            aria-label="Go to Home"
          >
             <div className="w-10 h-10 bg-[var(--accent)] rounded-2xl flex items-center justify-center text-black font-brand font-bold text-lg shadow-[0_0_25px_var(--shadow-glow)] group-hover:scale-110 transition-transform">O</div>
             <span className="font-brand font-bold tracking-[0.4em] text-sm text-[var(--text-primary)] uppercase">Obscura</span>
          </div>
        </div>

        <div className="px-6 mb-8 space-y-3">
           {currentProject ? (
             <div className="bg-[var(--bg-panel)] rounded-2xl p-5 border border-[var(--border-subtle)]" id="project-status">
               <div className="text-[9px] text-[var(--text-muted)] uppercase tracking-[0.3em] font-black font-mono">Archive Active</div>
               <div className="text-sm font-semibold truncate mt-1">{currentProject.name}</div>
               <div className="flex items-center gap-2 mt-4">
                 <div className={`w-2 h-2 rounded-full ${autoSaveStatus === 'saved' ? 'bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.4)]' : 'bg-[var(--accent)] animate-pulse shadow-[0_0_8px_var(--shadow-glow)]'}`}></div>
                 <span className="text-[10px] text-[var(--text-secondary)] font-mono uppercase tracking-wider">
                    {autoSaveStatus === 'saved' && isDriveConnected ? '🔒 VAULT SECURE' : autoSaveStatus}
                 </span>
               </div>
             </div>
           ) : (
             <button 
                onClick={() => isDriveConnected ? setShowSaveModal(true) : requestDriveToken()}
                className="w-full py-3.5 bg-transparent border border-[var(--border-subtle)] text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:border-[var(--text-secondary)] rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] transition-all flex items-center justify-center gap-3 active:scale-95"
                aria-label={isDriveConnected ? 'Sync Project to Vault' : 'Link Google Drive'}
             >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13.828 10.172a4 4 0 00-5.656 0l-4 4a4 4 0 105.656 5.656l1.102-1.101" /></svg>
                {isDriveConnected ? 'Sync Vault' : 'Link Drive'}
             </button>
           )}
           <button 
              onClick={handleLoadList}
              className="w-full py-3.5 bg-transparent border border-[var(--border-subtle)] text-[var(--text-muted)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-panel)] rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] transition-all flex items-center justify-center gap-3"
              aria-label="Load Archived Project"
           >
              Load Archive
           </button>
        </div>

        <div className="flex-1 overflow-y-auto px-4 space-y-1 py-4 border-t border-[var(--border-subtle)] custom-scrollbar">
           <button
              onClick={() => setCurrentView('HOME')}
              className={`w-full flex items-center gap-4 px-5 py-3 rounded-xl text-xs transition-all mb-4 ${
                currentView === 'HOME' 
                  ? 'bg-[var(--bg-panel)] text-[var(--accent)] font-bold border-l-4 border-[var(--accent)]' 
                  : 'text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-panel)]'
              }`}
              aria-current={currentView === 'HOME' ? 'page' : undefined}
           >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" /></svg>
              Home
           </button>

           <div className="px-5 text-[9px] font-black text-[var(--text-muted)] uppercase tracking-[0.3em] mb-3 mt-6 font-mono">Neural Systems</div>
           {MODULES.map((mod) => (
             <Tooltip key={mod.id} content={mod.subtitle} position="right">
               <button
                 onClick={() => setCurrentView(mod.id)}
                 className={`w-full flex items-center gap-4 px-5 py-3 rounded-xl text-xs transition-all ${
                   currentView === mod.id 
                     ? 'bg-[var(--bg-panel)] text-[var(--accent)] font-bold border-l-4 border-[var(--accent)]' 
                     : 'text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-panel)]'
                 }`}
                 aria-label={`Open ${mod.title} Module`}
                 aria-current={currentView === mod.id ? 'page' : undefined}
               >
                 <svg className={`w-4 h-4 transition-all duration-500 ${currentView === mod.id ? 'opacity-100' : 'opacity-20'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={mod.icon} /></svg>
                 {mod.title}
               </button>
             </Tooltip>
           ))}

           <div className="px-5 text-[9px] font-black text-[var(--text-muted)] uppercase tracking-[0.3em] mb-3 mt-10 font-mono">System Terminal</div>
           <button
              onClick={() => setCurrentView('GUIDE')}
              className={`w-full flex items-center gap-4 px-5 py-3 rounded-xl text-xs transition-all ${
                currentView === 'GUIDE' 
                  ? 'bg-[var(--bg-panel)] text-[var(--accent)] font-bold border-l-4 border-[var(--accent)]' 
                  : 'text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-panel)]'
              }`}
              aria-label="Operator's Guide"
           >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>
              Operator's Guide
           </button>
           <button
              onClick={() => setCurrentView('FAQ')}
              className={`w-full flex items-center gap-4 px-5 py-3 rounded-xl text-xs transition-all ${
                currentView === 'FAQ' 
                  ? 'bg-[var(--bg-panel)] text-[var(--accent)] font-bold border-l-4 border-[var(--accent)]' 
                  : 'text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-panel)]'
              }`}
              aria-label="FAQ"
           >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.228 9c.549-1.165 2.03-2 3.772-2 2.21 0 4 1.343 4 3 0 1.4-1.278 2.575-3.006 2.907-.542.104-.994.54-.994 1.093m0 3h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
              F.A.Q.
           </button>
           <button
              onClick={() => setCurrentView('SUPPORT')}
              className={`w-full flex items-center gap-4 px-5 py-3 rounded-xl text-xs transition-all ${
                currentView === 'SUPPORT' 
                  ? 'bg-[var(--bg-panel)] text-[var(--accent)] font-bold border-l-4 border-[var(--accent)]' 
                  : 'text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-panel)]'
              }`}
              aria-label="Support"
           >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M18.364 5.636l-3.536 3.536m0 5.656l3.536 3.536M9.172 9.172L5.636 5.636m3.536 9.192l-3.536 3.536M21 12a9 9 0 11-18 0 9 9 0 0118 0zm-5 0a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
              Support Uplink
           </button>
        </div>

        <div className="p-8 border-t border-[var(--border-subtle)] flex items-center gap-5">
           <div className="w-12 h-12 rounded-2xl bg-[var(--bg-studio)] border border-[var(--border-subtle)] flex items-center justify-center text-sm font-bold text-[var(--text-muted)] overflow-hidden shadow-2xl">
             {user.picture ? <img src={user.picture} alt="" className="w-full h-full object-cover" /> : user.name[0]}
           </div>
           <div className="flex-1 min-w-0 text-left">
             <div className="text-xs font-bold truncate">{user.name}</div>
             <button onClick={onLogout} className="text-[9px] text-[var(--text-muted)] hover:text-[var(--accent)] transition-colors uppercase tracking-[0.3em] font-black mt-1" aria-label="Disconnect">Disconnect</button>
           </div>
           <button onClick={() => setShowSettings(true)} className="p-3 text-[var(--text-muted)] hover:text-[var(--accent)] transition-colors" aria-label="Open Settings">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
           </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col relative min-w-0 bg-[var(--bg-studio)]">
         <div className="flex-1 overflow-y-auto relative custom-scrollbar">
           {isLoadingDrive && (
             <div className="absolute inset-0 bg-[var(--bg-studio)]/80 backdrop-blur-md z-50 flex items-center justify-center">
               <div className="w-12 h-12 border-2 border-[var(--border-subtle)] border-t-[var(--accent)] rounded-full animate-spin"></div>
             </div>
           )}

           {currentView === 'HOME' && (
             <div className="p-8 md:p-24 max-w-7xl mx-auto" id="modules-grid">
                <header className="mb-24 text-center md:text-left">
                   <h1 className="text-4xl md:text-7xl font-bold mb-6 tracking-tighter animate-fade-in">
                     Cinematic Intelligence suite <span className="text-[var(--text-muted)] font-mono text-xl ml-4 select-none hidden md:inline">v1.0.4</span>
                   </h1>
                </header>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 md:gap-12 animate-slide-up">
                   {MODULES.map(mod => (
                     <button key={mod.id} onClick={() => setCurrentView(mod.id)} className={cardStyle} aria-label={`Open ${mod.title} Module`}>
                        <div className="p-5 rounded-2xl bg-[var(--accent)]/5 text-[var(--accent)] w-fit mb-12 group-hover:scale-110 group-hover:bg-[var(--accent)]/10 transition-all duration-700 shadow-xl border border-transparent group-hover:border-[var(--accent)]/20">
                           <svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d={mod.icon} /></svg>
                        </div>
                        <div className="space-y-4">
                           <h3 className="text-3xl font-bold tracking-tighter group-hover:text-[var(--accent)] transition-colors duration-500">{mod.title}</h3>
                           <p className="text-sm text-[var(--text-secondary)] leading-relaxed min-h-[5rem] group-hover:text-[var(--text-primary)] transition-colors duration-500">
                             {mod.description}
                           </p>
                        </div>
                        <div className="mt-12 pt-8 border-t border-[var(--border-subtle)] flex items-center justify-between opacity-0 group-hover:opacity-100 transition-all duration-700 translate-y-4 group-hover:translate-y-0">
                           <span className="text-[10px] font-black text-[var(--accent)] uppercase tracking-[0.4em] flex items-center gap-3">
                              Initialize
                              <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
                           </span>
                           <span className="text-[9px] text-[var(--text-muted)] font-mono select-none uppercase tracking-widest">Sys_Ready</span>
                        </div>
                     </button>
                   ))}
                </div>
             </div>
           )}

           {activeModule && (
             <ActiveModule 
                module={activeModule} 
                history={moduleHistory[activeModule.id] || []}
                onResultGenerated={(r) => handleModuleResult(activeModule.id, r)}
                onUpdateHistory={(r) => handleUpdateLastLog(activeModule.id, r)}
                onExitModule={() => setCurrentView('HOME')}
                onToggleSidebar={() => setIsSidebarOpen(true)}
             />
           )}

           {currentView === 'GUIDE' && <div className="p-8 md:p-24"><Guide /></div>}
           {currentView === 'FAQ' && <div className="p-8 md:p-24"><FAQ /></div>}
           {currentView === 'SUPPORT' && <div className="p-8 md:p-24"><Support /></div>}
         </div>
      </main>

      <SaveProjectModal isOpen={showSaveModal} onCancel={() => setShowSaveModal(false)} onSave={handleCreateNewSave} />

      {showSettings && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/60 backdrop-blur-2xl animate-fade-in p-6" onClick={() => setShowSettings(false)}>
          <div className="bg-[var(--bg-panel)] border border-[var(--border-subtle)] w-full max-w-lg rounded-[3rem] shadow-2xl overflow-hidden text-[var(--text-primary)]" onClick={(e) => e.stopPropagation()}>
             <div className="p-10 border-b border-[var(--border-subtle)] flex justify-between items-center">
               <h3 className="text-2xl font-bold tracking-tight">System Core</h3>
               <button onClick={() => setShowSettings(false)} className="text-[var(--text-muted)] hover:text-[var(--text-primary)] bg-[var(--border-subtle)] p-3 rounded-2xl transition-colors" aria-label="Close Settings">✕</button>
             </div>
             <div className="p-10 space-y-12 overflow-y-auto max-h-[70vh] custom-scrollbar">
                <div>
                   <label className="block text-[9px] font-black text-[var(--text-muted)] uppercase tracking-[0.3em] mb-6 font-mono">Aesthetics Engine</label>
                   <div className="flex bg-[var(--bg-studio)] p-1.5 rounded-2xl border border-[var(--border-subtle)] shadow-inner">
                      <button onClick={() => setTheme('dark')} className={`flex-1 flex items-center justify-center gap-3 py-4 text-xs font-bold rounded-xl transition-all ${theme === 'dark' ? 'bg-[var(--bg-panel)] text-[var(--text-primary)] shadow-lg' : 'text-[var(--text-muted)] hover:text-[var(--text-secondary)]'}`}>
                         Obsidian Matte
                      </button>
                      <button onClick={() => setTheme('light')} className={`flex-1 flex items-center justify-center gap-3 py-4 text-xs font-bold rounded-xl transition-all ${theme === 'light' ? 'bg-[var(--bg-panel)] text-[var(--text-primary)] shadow-lg border border-[var(--border-subtle)]' : 'text-[var(--text-muted)] hover:text-[var(--text-secondary)]'}`}>
                         Daylight
                      </button>
                   </div>
                </div>
                <div>
                  <label className="block text-[9px] font-black text-[var(--text-muted)] uppercase tracking-[0.3em] mb-6 font-mono">Maintenance</label>
                  <div className="space-y-4">
                     <button onClick={handleClearCache} className="w-full bg-[var(--border-subtle)] text-[var(--text-secondary)] hover:bg-[var(--bg-studio)] hover:text-[var(--text-primary)] py-4 rounded-2xl text-[9px] font-black uppercase tracking-[0.3em] transition-all border border-transparent hover:border-[var(--text-muted)]">Clear Analysis Cache</button>
                     <button onClick={handleRestartTour} className="w-full bg-[var(--border-subtle)] text-[var(--text-secondary)] hover:bg-[var(--bg-studio)] hover:text-[var(--text-primary)] py-4 rounded-2xl text-[9px] font-black uppercase tracking-[0.3em] transition-all border border-transparent hover:border-[var(--text-muted)]">Replay Onboarding</button>
                  </div>
                </div>
                <div>
                  <label className="block text-[9px] font-black text-[var(--text-muted)] uppercase tracking-[0.3em] mb-6 font-mono">Neural Status</label>
                  <div className="bg-[var(--bg-studio)] border border-[var(--border-subtle)] rounded-3xl p-8 shadow-inner">
                    <div className="flex items-center gap-4 mb-6 text-green-500">
                      <div className="w-2.5 h-2.5 bg-green-500 rounded-full animate-pulse shadow-[0_0_15px_rgba(34,197,94,0.6)]"></div>
                      <span className="text-xs font-bold font-mono uppercase tracking-tighter">System Ready</span>
                    </div>
                    <p className="text-xs text-[var(--text-secondary)] mb-8 leading-relaxed font-light">
                      Encryption active. All neural processing is secured via your primary environment key.
                    </p>
                    <div className="grid grid-cols-1 gap-3">
                      <button onClick={onLogout} className="w-full bg-red-500/10 text-red-500 hover:bg-red-500 hover:text-white py-4 rounded-2xl text-[9px] font-black uppercase tracking-[0.3em] transition-all border border-red-500/20">Disconnect System</button>
                    </div>
                  </div>
                </div>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useRef, useContext, useEffect } from 'react';
import { ModuleDefinition, ModuleId, StoryboardFrame } from '../types';
import { streamModuleContent, generateSingleFrame } from '../services/geminiService';
import { generateCinematicImage } from '../services/bananaProService';
import { ApiKeyContext } from '../contexts/ApiKeyContext';
import MobileHeader from './MobileHeader';
import Toast from './Toast';

interface ActiveModuleProps {
  module: ModuleDefinition;
  history: string[];
  onResultGenerated: (result: string) => void;
  onUpdateHistory?: (result: string) => void;
  onExitModule: () => void;
  onToggleSidebar: () => void;
}

const ActiveModule: React.FC<ActiveModuleProps> = ({ module, history, onResultGenerated, onUpdateHistory, onExitModule, onToggleSidebar }) => {
  const apiKey = useContext(ApiKeyContext);
  const [textInput, setTextInput] = useState('');
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);

  const [loading, setLoading] = useState(false);
  const [thinkingState, setThinkingState] = useState<'idle' | 'processing' | 'complete'>('idle');
  const [isFadingOut, setIsFadingOut] = useState(false);
  const [timeLeft, setTimeLeft] = useState(0); // Progress timer

  const [exporting, setExporting] = useState(false);
  const [output, setOutput] = useState<string | null>(null);
  const [storyboardData, setStoryboardData] = useState<StoryboardFrame[]>([]);

  const [thinkingStepIndex, setThinkingStepIndex] = useState(0);

  const [editingFrameIndex, setEditingFrameIndex] = useState<number | null>(null);
  const [editedFrameData, setEditedFrameData] = useState<StoryboardFrame | null>(null);
  const [regeneratingIndex, setRegeneratingIndex] = useState<number | null>(null);
  const [generatingImageIndex, setGeneratingImageIndex] = useState<number | null>(null);

  const [errorToast, setErrorToast] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const storyboardRef = useRef<HTMLDivElement>(null);
  const endOfOutputRef = useRef<HTMLDivElement>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    endOfOutputRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [output, storyboardData, thinkingState]);

  useEffect(() => {
    if (history.length > 0) {
      processOutput(history[history.length - 1]);
    } else {
      setOutput(null);
      setStoryboardData([]);
    }
  }, [module.id, history]);

  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (thinkingState === 'processing') {
      setIsFadingOut(false);
      setThinkingStepIndex(0);
      setTimeLeft(45); // Start 45s countdown

      interval = setInterval(() => {
        setThinkingStepIndex(prev => prev < module.steps.length - 1 ? prev + 1 : prev);
        setTimeLeft(prev => Math.max(0, prev - 1));
      }, 1000); // Update every second
    } else if (thinkingState === 'complete') {
        setThinkingStepIndex(module.steps.length - 1);
        const timer = setTimeout(() => {
            setIsFadingOut(true);
            setTimeout(() => {
              setThinkingState('idle');
              setIsFadingOut(false);
            }, 600);
        }, 1500);
        return () => clearTimeout(timer);
    }
    return () => clearInterval(interval);
  }, [thinkingState, module.steps]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setImageFile(file);
      const reader = new FileReader();
      reader.onloadend = () => setImagePreview(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const processOutput = (result: string) => {
    if (module.id === ModuleId.STORYBOARD) {
      try {
        const frames = JSON.parse(result);
        setStoryboardData(Array.isArray(frames) ? frames : []);
      } catch (e) {
        // If JSON fails to parse (e.g. timeout returned partial), keep raw text or handle error
        if (result.trim().startsWith('[')) {
             setErrorToast("Partial storyboard data received. Try simpler input.");
        }
        setOutput(result);
      }
    } else {
      setOutput(result);
    }
  };

  const handleExecute = async (manualInput?: string) => {
    const inputToUse = manualInput || textInput;
    if (!inputToUse.trim() && !imageFile) return;

    // Cancel previous request if active
    if (abortControllerRef.current) {
        abortControllerRef.current.abort();
    }

    const controller = new AbortController();
    abortControllerRef.current = controller;

    setLoading(true);
    setThinkingState('processing');
    setStoryboardData([]);
    setOutput('');
    setErrorToast(null);

    // Safety Timeout (Client-side)
    const timeoutId = setTimeout(() => {
        if (abortControllerRef.current === controller) {
            controller.abort();
            setErrorToast("Connection timed out (45s). Network latency high.");
            setLoading(false);
            setThinkingState('idle');
        }
    }, 45000); // 45 Seconds Max

    let buffer = '';
    try {
      const result = await streamModuleContent(
        module.id, 
        inputToUse, 
        imageFile,
        (chunk) => {
            buffer += chunk;
            if (module.id !== ModuleId.STORYBOARD) setOutput(buffer);
        },
        controller.signal
      );

      clearTimeout(timeoutId);
      onResultGenerated(result);
      processOutput(result);
      setTextInput(''); // Only clear if success
      setImageFile(null);
      setImagePreview(null);
      setThinkingState('complete');
    } catch (err: any) {
      clearTimeout(timeoutId);
      if (err.message === "Request timed out by operator.") {
         setErrorToast("Operation cancelled.");
      } else {
         setErrorToast(err.message || "Neural uplink failure.");
      }
      // If we have partial buffer, show it
      if (buffer && module.id !== ModuleId.STORYBOARD) setOutput(buffer);
      setThinkingState('idle');
    } finally {
      setLoading(false);
      abortControllerRef.current = null;
    }
  };

  const handleCancel = () => {
    if (abortControllerRef.current) {
        abortControllerRef.current.abort();
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleExecute();
    }
  };

  const handleCopy = () => {
    if (!output) return;
    // Strip HTML for clipboard but keep logic simple
    const tmp = document.createElement("DIV");
    tmp.innerHTML = output;
    const cleanText = tmp.textContent || tmp.innerText || "";
    navigator.clipboard.writeText(cleanText).then(() => {
      // Could show a mini-toast here if needed
    });
  };

  const handleEditFrame = (index: number) => {
    setEditingFrameIndex(index);
    setEditedFrameData({ ...storyboardData[index] });
  };

  const handleSaveEdit = () => {
    if (editingFrameIndex !== null && editedFrameData) {
      const newData = [...storyboardData];
      newData[editingFrameIndex] = editedFrameData;
      setStoryboardData(newData);
      if (onUpdateHistory) onUpdateHistory(JSON.stringify(newData));
      setEditingFrameIndex(null);
    }
  };

  const handleRegenerateFrame = async (index: number) => {
    const frame = editingFrameIndex === index ? editedFrameData! : storyboardData[index];
    setRegeneratingIndex(index);
    try {
      const specs = `${frame.shotType}, ${frame.cameraMovement}, ${frame.composition}`;
      const newSvg = await generateSingleFrame(frame.description, specs);
      const newData = [...storyboardData];
      if (editingFrameIndex === index) setEditedFrameData({ ...frame, svg: newSvg });
      else {
        newData[index] = { ...frame, svg: newSvg };
        setStoryboardData(newData);
        if (onUpdateHistory) onUpdateHistory(JSON.stringify(newData));
      }
    } catch (e) { setErrorToast("Redraw failed. Try again."); } 
    finally { setRegeneratingIndex(null); }
  };

  const handleGenerateRealImage = async (index: number) => {
    const frame = storyboardData[index];
    setGeneratingImageIndex(index);
    try {
      const prompt = `Cinematic shot, ${frame.shotType}. ${frame.description}. Lighting: ${frame.lightingNotes}. Style: ${frame.composition}. Photorealistic 8k.`;
      const base64Image = await generateCinematicImage(prompt, apiKey);
      const newData = [...storyboardData];
      newData[index] = { ...frame, generatedImage: base64Image };
      setStoryboardData(newData);
      if (onUpdateHistory) onUpdateHistory(JSON.stringify(newData));
    } catch (e) { setErrorToast("Gen failed."); }
    finally { setGeneratingImageIndex(null); }
  };

  const handleExportPDF = async () => {
    if (!storyboardRef.current || !window.jspdf) return;
    setExporting(true);
    try {
       const { jsPDF } = window.jspdf;
       const doc = new jsPDF('p', 'mm', 'a4');
       const els = storyboardRef.current.querySelectorAll('.storyboard-frame');
       for (let i = 0; i < els.length; i++) {
         if (i > 0) doc.addPage();
         const canvas = await window.html2canvas(els[i] as HTMLElement, { scale: 2, backgroundColor: '#ffffff' });
         const imgData = canvas.toDataURL('image/jpeg', 0.9);
         doc.addImage(imgData, 'JPEG', 10, 10, 190, 0);
       }
       doc.save(`OBSCURA_${module.id}_Story.pdf`);
    } catch(e) { console.error(e); setErrorToast("Export failed."); }
    finally { setExporting(false); }
  };

  const renderContent = () => {
    if (!output && !storyboardData.length && thinkingState === 'idle') {
       return (
         <div className="absolute inset-0 flex flex-col items-center justify-center animate-fade-in p-10 pointer-events-none">
            <div className="text-[var(--text-primary)] animate-breathe mb-12 transform scale-[4]">
               <svg className="w-24 h-24" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={0.5} d={module.icon} /></svg>
            </div>

            <div className="text-center space-y-4 max-w-md">
               <h3 className="text-3xl font-bold tracking-tight">{module.title}</h3>
               <p className="text-[var(--text-secondary)] text-sm leading-relaxed font-light">{module.description}</p>
            </div>
         </div>
       );
    }

    return (
      <div className="max-w-5xl mx-auto w-full pb-72 pt-16 px-8">
        {thinkingState !== 'idle' && (
           <div className={`mb-16 bg-[var(--bg-panel)] border border-[var(--border-subtle)] backdrop-blur-xl rounded-[2.5rem] p-8 flex items-center gap-8 shadow-2xl transition-all duration-1000 transform ${isFadingOut ? 'opacity-0 -translate-y-12 scale-95 overflow-hidden' : 'opacity-100'}`}>
              <div className="relative w-14 h-14 flex items-center justify-center shrink-0">
                 {thinkingState === 'complete' ? (
                   <div className="text-[var(--accent)] animate-scale-in">
                      <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>
                   </div>
                 ) : (
                   <>
                     <div className="absolute inset-0 border-[3px] border-[var(--accent)]/10 rounded-full"></div>
                     <div className="absolute inset-0 border-[3px] border-[var(--accent)] border-t-transparent rounded-full animate-spin"></div>
                     <div className="text-[9px] font-black text-[var(--accent)] font-mono tracking-tighter">{timeLeft}s</div>
                   </>
                 )}
              </div>
              <div className="flex-1 min-w-0 text-left">
                 <h4 className="text-[9px] font-black text-[var(--accent)] uppercase tracking-[0.4em] mb-1.5 font-mono select-none">
                    {thinkingState === 'complete' ? 'Synthesis Converged' : 'Neural Processing'}
                 </h4>
                 <div className="flex items-center justify-between gap-4">
                   <div className="flex items-center gap-2">
                     <span className="text-xl font-bold truncate tracking-tight">
                        {thinkingState === 'complete' ? 'Success' : `${module.steps[thinkingStepIndex]}`}
                     </span>
                     {thinkingState === 'processing' && <span className="animate-pulse text-[var(--accent)] font-mono text-xl">_</span>}
                   </div>

                   {thinkingState === 'processing' && (
                     <button 
                       onClick={handleCancel}
                       className="px-4 py-2 border border-red-500/30 bg-red-500/10 text-red-500 rounded-xl text-[9px] font-black uppercase tracking-[0.2em] hover:bg-red-500 hover:text-white transition-all"
                     >
                       Abort
                     </button>
                   )}
                 </div>
              </div>
           </div>
        )}

        {output && module.id !== ModuleId.STORYBOARD && (
          <div className="bg-[var(--bg-card)] border border border-[var(--border-subtle)] rounded-[3rem] p-12 shadow-sm animate-slide-up backdrop-blur-[2px] relative group">
             <button 
                onClick={handleCopy}
                className="absolute top-6 right-6 opacity-0 group-hover:opacity-100 transition-opacity p-3 text-[var(--text-muted)] hover:text-[var(--accent)] bg-[var(--bg-studio)] rounded-xl border border-[var(--border-subtle)]"
                aria-label="Copy output to clipboard"
                title="Copy to Clipboard"
             >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
             </button>
             <div 
               className="prose prose-invert max-w-none text-[var(--text-secondary)] font-inter text-sm leading-[1.8] marker:text-[var(--accent)]"
               dangerouslySetInnerHTML={{ __html: output }}
             />
          </div>
        )}

        {storyboardData.length > 0 && (
          <div ref={storyboardRef} className="space-y-16 animate-slide-up">
             <div className="flex justify-between items-end border-b border-[var(--border-subtle)] pb-8">
                <div>
                  <h3 className="text-4xl font-bold tracking-tighter">Visual Archive</h3>
                  <p className="text-[var(--text-muted)] text-sm mt-2 font-light tracking-wide">Analysis Log // Sequence 01</p>
                </div>
                <button onClick={handleExportPDF} disabled={exporting} className="bg-[var(--text-primary)] text-[var(--bg-studio)] px-8 py-3 rounded-[1.25rem] text-[9px] font-black uppercase tracking-[0.2em] hover:bg-[var(--accent)] hover:text-black transition-all active:scale-95 shadow-xl" aria-label="Export PDF Dossier">
                  {exporting ? 'Processing' : 'Export Dossier'}
                </button>
             </div>

             <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
               {storyboardData.map((frame, idx) => {
                 const isEditing = editingFrameIndex === idx;
                 const data = isEditing ? editedFrameData! : frame;
                 const isBusy = regeneratingIndex === idx || generatingImageIndex === idx;

                 return (
                   <div key={idx} className="storyboard-frame bg-[var(--bg-card)] border border-[var(--border-subtle)] rounded-[2.5rem] overflow-hidden group hover:border-[var(--accent)]/30 transition-all duration-700">
                      <div className="aspect-video bg-white relative flex items-center justify-center overflow-hidden">
                         {isBusy && (
                           <div className="absolute inset-0 bg-white/95 z-20 flex items-center justify-center">
                              <div className="w-10 h-10 border-4 border-black border-t-transparent rounded-full animate-spin"></div>
                           </div>
                         )}
                         {data.generatedImage ? (
                           <img src={data.generatedImage} alt={`Frame ${idx+1}: ${data.description}`} className="w-full h-full object-cover" />
                         ) : (
                           <div className="p-12 w-full h-full opacity-90 scale-105 group-hover:scale-100 transition-transform duration-1000" dangerouslySetInnerHTML={{ __html: data.svg }} />
                         )}
                         <div className="absolute top-6 right-6 flex gap-3 opacity-0 group-hover:opacity-100 transition-all translate-y-3 group-hover:translate-y-0">
                            {!data.generatedImage && (
                              <button onClick={() => handleGenerateRealImage(idx)} className="bg-black text-white px-4 py-2 rounded-xl text-[8px] font-black uppercase tracking-widest hover:bg-[var(--accent)] hover:text-black transition-all shadow-2xl" aria-label="Render High-Fidelity Image">
                                 Render High-Fi
                              </button>
                            )}
                         </div>
                      </div>

                      <div className="p-10 text-sm">
                         {isEditing ? (
                           <div className="space-y-6">
                             <textarea className="w-full bg-[var(--bg-studio)] text-[var(--text-primary)] p-5 rounded-3xl text-xs border border-[var(--border-subtle)] outline-none focus:border-[var(--accent)]/50 transition-colors font-mono" rows={3} value={data.description} onChange={e => setEditedFrameData({...data, description: e.target.value})} />
                             <div className="flex gap-3">
                               <button onClick={() => handleRegenerateFrame(idx)} className="flex-1 bg-[var(--border-subtle)] py-3 rounded-2xl text-[9px] font-black text-[var(--text-muted)] uppercase tracking-widest">Redraw</button>
                               <button onClick={handleSaveEdit} className="flex-1 bg-[var(--accent)] text-black py-3 rounded-2xl text-[9px] font-black uppercase tracking-[0.2em]">Commit</button>
                             </div>
                           </div>
                         ) : (
                           <div className="space-y-6">
                             <div className="flex justify-between items-center text-left">
                               <span className="text-[9px] font-black text-[var(--accent)] uppercase tracking-[0.4em] font-mono select-none">F0{idx+1} // {data.shotType}</span>
                               <button onClick={() => handleEditFrame(idx)} className="text-[var(--text-muted)] hover:text-[var(--accent)] transition-colors bg-[var(--border-subtle)] p-2 rounded-lg" aria-label={`Edit Frame ${idx+1}`}>
                                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
                               </button>
                             </div>
                             <p className="text-[var(--text-primary)] text-left font-medium leading-relaxed line-clamp-3 text-base">{data.description}</p>
                             <div className="pt-6 border-t border-[var(--border-subtle)] flex gap-6 text-[9px] text-[var(--text-muted)] font-mono uppercase tracking-[0.1em] select-none">
                               <span className="bg-[var(--border-subtle)] px-2 py-1 rounded">{data.focalLength}</span>
                               <span className="bg-[var(--border-subtle)] px-2 py-1 rounded">{data.cameraMovement}</span>
                             </div>
                           </div>
                         )}
                      </div>
                   </div>
                 );
               })}
             </div>
          </div>
        )}
        <div ref={endOfOutputRef} />
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full relative">
      <MobileHeader 
        title={module.title} 
        onBack={onExitModule} 
        onOpenSettings={onToggleSidebar}
      />

      <div className="flex-1 overflow-y-auto custom-scrollbar pt-20 md:pt-0">
        {renderContent()}
      </div>

      {errorToast && <Toast message={errorToast} onClose={() => setErrorToast(null)} />}

      {/* Monolith Floating Input Console */}
      <div className="absolute bottom-12 left-0 right-0 px-8 z-30 pointer-events-none">
        <div className="max-w-3xl mx-auto pointer-events-auto">
           {imagePreview && (
             <div className="mb-6 bg-[var(--bg-studio)] border border-[var(--border-subtle)] rounded-[2rem] p-3 w-fit flex items-center gap-4 shadow-[0_20px_40px_rgba(0,0,0,0.4)] animate-slide-up border-b-[var(--accent)]/50">
               <img src={imagePreview} className="w-12 h-12 rounded-xl object-cover" alt="Upload preview" />
               <button onClick={() => {setImageFile(null); setImagePreview(null);}} className="text-[var(--text-muted)] hover:text-red-500 pr-3 transition-colors" aria-label="Remove image">✕</button>
             </div>
           )}

           <div className="bg-[var(--bg-panel)] backdrop-blur-2xl border border-[var(--border-subtle)] rounded-[2.5rem] shadow-[0_40px_80px_-20px_rgba(0,0,0,0.5)] flex items-end p-2.5 transition-all duration-500 focus-within:border-[var(--accent)]/50 focus-within:shadow-[0_0_25px_var(--shadow-glow)]">
              {module.requiresImage && (
                <button onClick={() => fileInputRef.current?.click()} className="p-5 text-[var(--text-muted)] hover:text-[var(--accent)] transition-all duration-300" title="Attach Visual Context" aria-label="Upload Image">
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                </button>
              )}
              <input type="file" ref={fileInputRef} onChange={handleImageUpload} className="hidden" accept="image/*" />

              <div className="flex-1 relative">
                 <span className="absolute left-5 top-5 text-[var(--accent)] font-mono text-base pointer-events-none select-none">&gt;_</span>
                 <textarea 
                   value={textInput}
                   onChange={(e) => setTextInput(e.target.value)}
                   onKeyDown={handleKeyDown}
                   placeholder={`Ask ${module.title.toUpperCase()}...`}
                   className="w-full bg-transparent text-[var(--text-primary)] placeholder-[var(--text-muted)] text-sm py-5 pl-12 pr-6 outline-none resize-none max-h-48 min-h-[64px] font-mono leading-relaxed"
                   rows={1}
                   style={{ height: 'auto', minHeight: '64px' }}
                   aria-label="Prompt Input"
                 />
              </div>

              <button 
                onClick={() => handleExecute()}
                disabled={loading || (!textInput.trim() && !imageFile)}
                className={`p-5 m-1 rounded-[1.75rem] transition-all duration-500 shadow-2xl ${
                   textInput.trim() || imageFile 
                     ? 'bg-[var(--accent)] text-black hover:bg-white active:scale-95 shadow-[var(--accent)]/20' 
                     : 'bg-[var(--bg-studio)] text-[var(--text-muted)] cursor-not-allowed opacity-30'
                }`}
                aria-label={loading ? 'Processing' : 'Initialize Agent'}
              >
                {loading ? (
                    <div className="w-6 h-6 border-2 border-black/30 border-t-black rounded-full animate-spin"></div>
                ) : (
                    <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
                      <path strokeLinecap="round" strokeLinejoin="round" d="M14 5l7 7m0 0l-7 7m7-7H3" />
                    </svg>
                )}
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

export default ActiveModule;

import React, { useState, useEffect, useCallback, ErrorInfo, ReactNode } from 'react';
import { AppState, UserProfile } from './types';
import Landing from './components/Landing';
import Dashboard from './components/Dashboard';
import Gatekeeper from './components/Gatekeeper';
import FlashlightCursor from './components/FlashlightCursor';
import { ApiKeyContext } from './contexts/ApiKeyContext';

interface ErrorBoundaryProps {
  children?: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: any;
}

// Error Boundary to prevent "Black Screen of Death"
class ErrorBoundary extends React.Component<ErrorBoundaryProps, ErrorBoundaryState> {
  public state: ErrorBoundaryState = {
    hasError: false,
    error: null
  };

  static getDerivedStateFromError(error: any): ErrorBoundaryState {
    return { hasError: true, error };
  }

  componentDidCatch(error: any, errorInfo: ErrorInfo) {
    console.error("Critical System Failure:", error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen bg-black text-red-500 flex flex-col items-center justify-center p-8 font-mono text-xs z-50 relative">
          <div className="max-w-xl w-full">
            <h1 className="text-xl mb-4 font-bold tracking-widest border-b border-red-900 pb-4">SYSTEM_FAILURE_DETECTED</h1>
            <p className="mb-4 text-zinc-400">The neural link encountered a critical exception.</p>
            <pre className="bg-[#111] p-6 rounded-xl overflow-auto border border-red-900/50 mb-8 font-mono text-[10px] leading-relaxed">
              {this.state.error?.toString()}
            </pre>
            <button 
              onClick={() => {
                localStorage.clear(); 
                window.location.reload();
              }}
              className="w-full border border-red-500/50 text-red-500 px-6 py-4 hover:bg-red-900/20 rounded-xl transition-all uppercase tracking-[0.2em] font-bold"
            >
              Initiate Hard Reset
            </button>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.LANDING);
  const [user, setUser] = useState<UserProfile | null>(null);

  // Use a safer initializer for the runtime key
  const [runtimeKey, setRuntimeKey] = useState<string>(() => {
    try {
      const win = window as any;
      const envKey = win.process?.env?.API_KEY;
      const storedKey = localStorage.getItem('obscura_api_key');
      return envKey || storedKey || '';
    } catch {
      return '';
    }
  });

  // Sync state on mount and handle auto-login
  useEffect(() => {
    const storedUser = localStorage.getItem('obscura_user');
    if (storedUser) {
      try {
        const parsedUser = JSON.parse(storedUser);
        setUser(parsedUser);

        const win = window as any;
        const key = win.process?.env?.API_KEY || localStorage.getItem('obscura_api_key') || '';

        if (key && key.length > 5) {
          setAppState(AppState.DASHBOARD);
        } else {
          setAppState(AppState.GATEKEEPER);
        }
      } catch (e) {
        console.error("Auth hydration failure", e);
        localStorage.removeItem('obscura_user');
        setAppState(AppState.LANDING);
      }
    }
  }, []);

  const handleSignIn = useCallback((userProfile: UserProfile) => {
    localStorage.setItem('obscura_user', JSON.stringify(userProfile));
    setUser(userProfile);

    const win = window as any;
    const currentKey = win.process?.env?.API_KEY || localStorage.getItem('obscura_api_key') || '';

    if (!currentKey || currentKey.length < 5) {
      setAppState(AppState.GATEKEEPER);
    } else {
      setRuntimeKey(currentKey);
      setAppState(AppState.DASHBOARD);
    }
  }, []);

  const handleGatePassed = useCallback((key?: string) => {
    if (key) {
      setRuntimeKey(key);
      const win = window as any;
      if (!win.process) win.process = { env: {} };
      win.process.env.API_KEY = key;
      localStorage.setItem('obscura_api_key', key);
    }
    setAppState(AppState.DASHBOARD);
  }, []);

  const handleLogout = useCallback(() => {
    localStorage.removeItem('obscura_user');
    setUser(null);
    setAppState(AppState.LANDING);
    window.scrollTo(0, 0);
  }, []);

  // Determine what to render based on state
  const renderView = () => {
    if (appState === AppState.DASHBOARD && user) {
      return <Dashboard user={user} onLogout={handleLogout} />;
    }

    if (appState === AppState.GATEKEEPER) {
      return <Gatekeeper onSuccess={handleGatePassed} />;
    }

    // Default fallback is always Landing
    return <Landing onSignIn={handleSignIn} />;
  };

  return (
    <ErrorBoundary>
      <ApiKeyContext.Provider value={runtimeKey}>
        <FlashlightCursor />
        {/* Main Content Container with High Z-Index to sit ABOVE the film grain */}
        <div className="min-h-screen bg-[#050505] relative z-20">
          {renderView()}
        </div>
      </ApiKeyContext.Provider>
    </ErrorBoundary>
  );
};

export default App;

