      const storedKey = localStorage.getItem('obscura_api_key');
      return envKey || storedKey || '';
    } catch {
      return '';
    }
  });

  // Sync state on mount and handle auto-login
  useEffect(() => {
    const storedUser = localStorage.getItem('obscura_user');
    if (storedUser) {
      try {
        const parsedUser = JSON.parse(storedUser);
        setUser(parsedUser);

        const win = window as any;
        const key = win.process?.env?.API_KEY || localStorage.getItem('obscura_api_key') || '';

        if (key && key.length > 5) {
          setAppState(AppState.DASHBOARD);
        } else {
          setAppState(AppState.GATEKEEPER);
        }
      } catch (e) {
        console.error("Auth hydration failure", e);
        localStorage.removeItem('obscura_user');
        setAppState(AppState.LANDING);
      }
    }
  }, []);

  const handleSignIn = useCallback((userProfile: UserProfile) => {
    localStorage.setItem('obscura_user', JSON.stringify(userProfile));
    setUser(userProfile);

    const win = window as any;
    const currentKey = win.process?.env?.API_KEY || localStorage.getItem('obscura_api_key') || '';

    if (!currentKey || currentKey.length < 5) {
      setAppState(AppState.GATEKEEPER);
    } else {
      setRuntimeKey(currentKey);
      setAppState(AppState.DASHBOARD);
    }
  }, []);

  const handleGatePassed = useCallback((key?: string) => {
    if (key) {
      setRuntimeKey(key);
      const win = window as any;
      if (!win.process) win.process = { env: {} };
      win.process.env.API_KEY = key;
      localStorage.setItem('obscura_api_key', key);
    }
    setAppState(AppState.DASHBOARD);
  }, []);

  const handleLogout = useCallback(() => {
    localStorage.removeItem('obscura_user');
    setUser(null);
    setAppState(AppState.LANDING);
    window.scrollTo(0, 0);
  }, []);

  // Determine what to render based on state
  const renderView = () => {
    if (appState === AppState.DASHBOARD && user) {
      return <Dashboard user={user} onLogout={handleLogout} />;
    }

    if (appState === AppState.GATEKEEPER) {
      return <Gatekeeper onSuccess={handleGatePassed} />;
    }

    // Default fallback is always Landing
    return <Landing onSignIn={handleSignIn} />;
  };

  return (
    <ErrorBoundary>
      <ApiKeyContext.Provider value={runtimeKey}>
        <FlashlightCursor />
        {/* Main Content Container with High Z-Index to sit ABOVE the film grain */}
        <div className="min-h-screen bg-[#050505] relative z-20">
          {renderView()}
        </div>
      </ApiKeyContext.Provider>
    </ErrorBoundary>
  );
};

export default App;

import React, { useState, useRef, useContext, useEffect } from 'react';
import { ModuleDefinition, ModuleId, StoryboardFrame } from '../types';
import { streamModuleContent, generateSingleFrame } from '../services/geminiService';
import { generateCinematicImage } from '../services/bananaProService';
import { ApiKeyContext } from '../contexts/ApiKeyContext';
import MobileHeader from './MobileHeader';
import Toast from './Toast';

interface ActiveModuleProps {
  module: ModuleDefinition;
  history: string[];
  onResultGenerated: (result: string) => void;
  onUpdateHistory?: (result: string) => void;
  onExitModule: () => void;
  onToggleSidebar: () => void;
}

const ActiveModule: React.FC<ActiveModuleProps> = ({ module, history, onResultGenerated, onUpdateHistory, onExitModule, onToggleSidebar }) => {
  const apiKey = useContext(ApiKeyContext);
  const [textInput, setTextInput] = useState('');

  // Media State (Images or PDFs)
  const [mediaFile, setMediaFile] = useState<File | null>(null);
  const [mediaType, setMediaType] = useState<'image' | 'application' | null>(null);
  const [mediaPreview, setMediaPreview] = useState<string | null>(null);

  const [loading, setLoading] = useState(false);
  const [thinkingState, setThinkingState] = useState<'idle' | 'processing' | 'complete'>('idle');
  const [isFadingOut, setIsFadingOut] = useState(false);
  const [timeLeft, setTimeLeft] = useState(0); // Progress timer

  const [exporting, setExporting] = useState(false);
  const [output, setOutput] = useState<string | null>(null);
  const [storyboardData, setStoryboardData] = useState<StoryboardFrame[]>([]);

  const [thinkingStepIndex, setThinkingStepIndex] = useState(0);

  const [editingFrameIndex, setEditingFrameIndex] = useState<number | null>(null);
  const [editedFrameData, setEditedFrameData] = useState<StoryboardFrame | null>(null);
  const [regeneratingIndex, setRegeneratingIndex] = useState<number | null>(null);
  const [generatingImageIndex, setGeneratingImageIndex] = useState<number | null>(null);

  const [errorToast, setErrorToast] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const storyboardRef = useRef<HTMLDivElement>(null);
  const endOfOutputRef = useRef<HTMLDivElement>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    endOfOutputRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [output, storyboardData, thinkingState]);

  useEffect(() => {
    if (history.length > 0) {
      processOutput(history[history.length - 1]);
    } else {
      setOutput(null);
      setStoryboardData([]);
    }
  }, [module.id, history]);

  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (thinkingState === 'processing') {
      setIsFadingOut(false);
      setThinkingStepIndex(0);
      setTimeLeft(45); // Start 45s countdown

      interval = setInterval(() => {
        setThinkingStepIndex(prev => prev < module.steps.length - 1 ? prev + 1 : prev);
        setTimeLeft(prev => Math.max(0, prev - 1));
      }, 1000); // Update every second
    } else if (thinkingState === 'complete') {
        setThinkingStepIndex(module.steps.length - 1);
        const timer = setTimeout(() => {
            setIsFadingOut(true);
            setTimeout(() => {
              setThinkingState('idle');
              setIsFadingOut(false);
            }, 600);
        }, 1500);
        return () => clearTimeout(timer);
    }
    return () => clearInterval(interval);
  }, [thinkingState, module.steps]);

  // Determine if this module supports file uploads (Image OR Script)
  const isScriptModule = module.id === ModuleId.STORYBOARD || module.id === ModuleId.SUBTEXT;
  const canUpload = module.requiresImage || isScriptModule;
  const uploadAccept = module.requiresImage ? "image/*" : ".txt,.md,.fountain,.json,.pdf";

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setErrorToast(null);

    if (module.requiresImage) {
        // Image Mode
        if (!file.type.startsWith('image/')) {
             setErrorToast("This module requires an image file.");
             return;
        }
        setMediaFile(file);
        setMediaType('image');
        const reader = new FileReader();
        reader.onloadend = () => setMediaPreview(reader.result as string);
        reader.readAsDataURL(file);
    } else {
        // Script Mode
        if (file.type === 'application/pdf') {
             setMediaFile(file);
             setMediaType('application');
             setMediaPreview(null);
             setErrorToast("PDF Script attached.");
        } else {
             // Text Mode (txt, md, fountain)
             const validExtensions = ['.txt', '.md', '.fountain', '.json'];
             const isTextType = file.type.startsWith('text/') || validExtensions.some(ext => file.name.toLowerCase().endsWith(ext));

             if (!isTextType) {
                  setErrorToast("Unsupported format. Use .pdf, .txt, .md, or .fountain.");
                  return;
             }

             const reader = new FileReader();
             reader.onload = (event) => {
                 const content = event.target?.result as string;
                 // Inject content directly into the input field for editable text
                 setTextInput(content); 
                 setErrorToast("Script text loaded.");
             };
             reader.onerror = () => setErrorToast("Failed to read file.");
             reader.readAsText(file);
        }
    }

    // Reset input so the same file can be selected again if needed
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const processOutput = (result: string) => {
    if (module.id === ModuleId.STORYBOARD) {
      try {
        const frames = JSON.parse(result);
        setStoryboardData(Array.isArray(frames) ? frames : []);
      } catch (e) {
        if (result.trim().startsWith('[')) {
             setErrorToast("Partial storyboard data received. Try simpler input.");
        }
        setOutput(result);
      }
    } else {
      setOutput(result);
    }
  };

  const handleExecute = async (manualInput?: string) => {
    const inputToUse = manualInput || textInput;
    if (!inputToUse.trim() && !mediaFile) return;

    // Cancel previous request if active
    if (abortControllerRef.current) {
        abortControllerRef.current.abort();
    }

    const controller = new AbortController();
    abortControllerRef.current = controller;

    setLoading(true);
    setThinkingState('processing');
    setStoryboardData([]);
    setOutput('');
    setErrorToast(null);

    // Safety Timeout (Client-side)
    const timeoutId = setTimeout(() => {
        if (abortControllerRef.current === controller) {
            controller.abort();
            setErrorToast("Connection timed out (45s). Network latency high.");
            setLoading(false);
            setThinkingState('idle');
        }
    }, 45000); // 45 Seconds Max

    let buffer = '';
    try {
      const result = await streamModuleContent(
        module.id, 
        inputToUse, 
        mediaFile, // Pass generic media file
        (chunk) => {
            buffer += chunk;
            if (module.id !== ModuleId.STORYBOARD) setOutput(buffer);
        },
        controller.signal
      );

      clearTimeout(timeoutId);
      onResultGenerated(result);
      processOutput(result);
      setTextInput(''); // Only clear input on success
      setMediaFile(null);
      setMediaType(null);
      setMediaPreview(null);
      setThinkingState('complete');
    } catch (err: any) {
      clearTimeout(timeoutId);
      if (err.message === "Request timed out by operator.") {
         setErrorToast("Operation cancelled.");
      } else {
         setErrorToast(err.message || "Neural uplink failure.");
      }
      if (buffer && module.id !== ModuleId.STORYBOARD) setOutput(buffer);
      setThinkingState('idle');
    } finally {
      setLoading(false);
      abortControllerRef.current = null;
    }
  };

  const handleCancel = () => {
    if (abortControllerRef.current) {
        abortControllerRef.current.abort();
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleExecute();
    }
  };

  const handleCopy = () => {
    if (!output) return;
    const tmp = document.createElement("DIV");
    tmp.innerHTML = output;
    const cleanText = tmp.textContent || tmp.innerText || "";
    navigator.clipboard.writeText(cleanText).then(() => {
       // Optional: show copy success toast
    });
  };

  const handleEditFrame = (index: number) => {
    setEditingFrameIndex(index);
    setEditedFrameData({ ...storyboardData[index] });
  };

  const handleSaveEdit = () => {
    if (editingFrameIndex !== null && editedFrameData) {
      const newData = [...storyboardData];
      newData[editingFrameIndex] = editedFrameData;
      setStoryboardData(newData);
      if (onUpdateHistory) onUpdateHistory(JSON.stringify(newData));
      setEditingFrameIndex(null);
    }
  };

  const handleRegenerateFrame = async (index: number) => {
    const frame = editingFrameIndex === index ? editedFrameData! : storyboardData[index];
    setRegeneratingIndex(index);
    try {
      const specs = `${frame.shotType}, ${frame.cameraMovement}, ${frame.composition}`;
      const newSvg = await generateSingleFrame(frame.description, specs);
      const newData = [...storyboardData];
      if (editingFrameIndex === index) setEditedFrameData({ ...frame, svg: newSvg });
      else {
        newData[index] = { ...frame, svg: newSvg };
        setStoryboardData(newData);
        if (onUpdateHistory) onUpdateHistory(JSON.stringify(newData));
      }
    } catch (e) { setErrorToast("Redraw failed. Try again."); } 
    finally { setRegeneratingIndex(null); }
  };

  const handleGenerateRealImage = async (index: number) => {
    const frame = storyboardData[index];
    setGeneratingImageIndex(index);
    try {
      const prompt = `Cinematic shot, ${frame.shotType}. ${frame.description}. Lighting: ${frame.lightingNotes}. Style: ${frame.composition}. Photorealistic 8k.`;
      const base64Image = await generateCinematicImage(prompt, apiKey);
      const newData = [...storyboardData];
      newData[index] = { ...frame, generatedImage: base64Image };
      setStoryboardData(newData);
      if (onUpdateHistory) onUpdateHistory(JSON.stringify(newData));
    } catch (e) { setErrorToast("Gen failed."); }
    finally { setGeneratingImageIndex(null); }
  };

  const handleExportPDF = async () => {
    if (!storyboardRef.current || !window.jspdf) return;
    setExporting(true);
    try {
       const { jsPDF } = window.jspdf;
       const doc = new jsPDF('p', 'mm', 'a4');
       const els = storyboardRef.current.querySelectorAll('.storyboard-frame');
       for (let i = 0; i < els.length; i++) {
         if (i > 0) doc.addPage();
         const canvas = await window.html2canvas(els[i] as HTMLElement, { scale: 2, backgroundColor: '#ffffff' });
         const imgData = canvas.toDataURL('image/jpeg', 0.9);
         doc.addImage(imgData, 'JPEG', 10, 10, 190, 0);
       }
       doc.save(`OBSCURA_${module.id}_Story.pdf`);
    } catch(e) { console.error(e); setErrorToast("Export failed."); }
    finally { setExporting(false); }
  };

  const renderContent = () => {
    if (!output && !storyboardData.length && thinkingState === 'idle') {
       return (
         <div className="absolute inset-0 flex flex-col items-center justify-center animate-fade-in p-10 pointer-events-none">
            <div className="text-[var(--text-primary)] animate-breathe mb-12 transform scale-[4]">
               <svg className="w-24 h-24" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={0.5} d={module.icon} /></svg>
            </div>

            <div className="text-center space-y-4 max-w-md">
               <h3 className="text-3xl font-bold tracking-tight">{module.title}</h3>
               <p className="text-[var(--text-secondary)] text-sm leading-relaxed font-light">{module.description}</p>
            </div>
         </div>
       );
    }

    return (
      <div className="max-w-5xl mx-auto w-full pb-72 pt-16 px-8">
        {thinkingState !== 'idle' && (
           <div className={`mb-16 bg-[var(--bg-panel)] border border-[var(--border-subtle)] backdrop-blur-xl rounded-[2.5rem] p-8 flex items-center gap-8 shadow-2xl transition-all duration-1000 transform ${isFadingOut ? 'opacity-0 -translate-y-12 scale-95 overflow-hidden' : 'opacity-100'}`}>
              <div className="relative w-14 h-14 flex items-center justify-center shrink-0">
                 {thinkingState === 'complete' ? (
                   <div className="text-[var(--accent)] animate-scale-in">
                      <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>
                   </div>
                 ) : (
                   <>
                     <div className="absolute inset-0 border-[3px] border-[var(--accent)]/10 rounded-full"></div>
                     <div className="absolute inset-0 border-[3px] border-[var(--accent)] border-t-transparent rounded-full animate-spin"></div>
                     <div className="text-[9px] font-black text-[var(--accent)] font-mono tracking-tighter">{timeLeft}s</div>
                   </>
                 )}
              </div>
              <div className="flex-1 min-w-0 text-left">
                 <h4 className="text-[9px] font-black text-[var(--accent)] uppercase tracking-[0.4em] mb-1.5 font-mono select-none">
                    {thinkingState === 'complete' ? 'Synthesis Converged' : 'Neural Processing'}
                 </h4>
                 <div className="flex items-center justify-between gap-4">
                   <div className="flex items-center gap-2">
                     <span className="text-xl font-bold truncate tracking-tight">
                        {thinkingState === 'complete' ? 'Success' : `${module.steps[thinkingStepIndex]}`}
                     </span>
                     {thinkingState === 'processing' && <span className="animate-pulse text-[var(--accent)] font-mono text-xl">_</span>}
                   </div>

                   {thinkingState === 'processing' && (
                     <button 
                       onClick={handleCancel}
                       className="px-4 py-2 border border-red-500/30 bg-red-500/10 text-red-500 rounded-xl text-[9px] font-black uppercase tracking-[0.2em] hover:bg-red-500 hover:text-white transition-all"
                     >
                       Abort
                     </button>
                   )}
                 </div>
              </div>
           </div>
        )}

        {output && module.id !== ModuleId.STORYBOARD && (
          <div className="bg-[var(--bg-card)] border border border-[var(--border-subtle)] rounded-[3rem] p-12 shadow-sm animate-slide-up backdrop-blur-[2px] relative group">
             <button 
                onClick={handleCopy}
                className="absolute top-6 right-6 opacity-0 group-hover:opacity-100 transition-opacity p-3 text-[var(--text-muted)] hover:text-[var(--accent)] bg-[var(--bg-studio)] rounded-xl border border-[var(--border-subtle)]"
                aria-label="Copy output to clipboard"
                title="Copy to Clipboard"
             >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
             </button>
             <div 
               className="prose prose-invert max-w-none text-[var(--text-secondary)] font-inter text-sm leading-[1.8] marker:text-[var(--accent)]"
               dangerouslySetInnerHTML={{ __html: output }}
             />
          </div>
        )}

        {storyboardData.length > 0 && (
          <div ref={storyboardRef} className="space-y-16 animate-slide-up">
             <div className="flex justify-between items-end border-b border-[var(--border-subtle)] pb-8">
                <div>
                  <h3 className="text-4xl font-bold tracking-tighter">Visual Archive</h3>
                  <p className="text-[var(--text-muted)] text-sm mt-2 font-light tracking-wide">Analysis Log // Sequence 01</p>
                </div>
                <button onClick={handleExportPDF} disabled={exporting} className="bg-[var(--text-primary)] text-[var(--bg-studio)] px-8 py-3 rounded-[1.25rem] text-[9px] font-black uppercase tracking-[0.2em] hover:bg-[var(--accent)] hover:text-black transition-all active:scale-95 shadow-xl" aria-label="Export PDF Dossier">
                  {exporting ? 'Processing' : 'Export Dossier'}
                </button>
             </div>

             <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
               {storyboardData.map((frame, idx) => {
                 const isEditing = editingFrameIndex === idx;
                 const data = isEditing ? editedFrameData! : frame;
                 const isBusy = regeneratingIndex === idx || generatingImageIndex === idx;

                 return (
                   <div key={idx} className="storyboard-frame bg-[var(--bg-card)] border border-[var(--border-subtle)] rounded-[2.5rem] overflow-hidden group hover:border-[var(--accent)]/30 transition-all duration-700">
                      <div className="aspect-video bg-white relative flex items-center justify-center overflow-hidden">
                         {isBusy && (
                           <div className="absolute inset-0 bg-white/95 z-20 flex items-center justify-center">
                              <div className="w-10 h-10 border-4 border-black border-t-transparent rounded-full animate-spin"></div>
                           </div>
                         )}
                         {data.generatedImage ? (
                           <img src={data.generatedImage} alt={`Frame ${idx+1}: ${data.description}`} className="w-full h-full object-cover" />
                         ) : (
                           <div className="p-12 w-full h-full opacity-90 scale-105 group-hover:scale-100 transition-transform duration-1000" dangerouslySetInnerHTML={{ __html: data.svg }} />
                         )}
                         <div className="absolute top-6 right-6 flex gap-3 opacity-0 group-hover:opacity-100 transition-all translate-y-3 group-hover:translate-y-0">
                            {!data.generatedImage && (
                              <button onClick={() => handleGenerateRealImage(idx)} className="bg-black text-white px-4 py-2 rounded-xl text-[8px] font-black uppercase tracking-widest hover:bg-[var(--accent)] hover:text-black transition-all shadow-2xl" aria-label="Render High-Fidelity Image">
                                 Render High-Fi
                              </button>
                            )}
                         </div>
                      </div>

                      <div className="p-10 text-sm">
                         {isEditing ? (
                           <div className="space-y-6">
                             <textarea className="w-full bg-[var(--bg-studio)] text-[var(--text-primary)] p-5 rounded-3xl text-xs border border-[var(--border-subtle)] outline-none focus:border-[var(--accent)]/50 transition-colors font-mono" rows={3} value={data.description} onChange={e => setEditedFrameData({...data, description: e.target.value})} />
                             <div className="flex gap-3">
                               <button onClick={() => handleRegenerateFrame(idx)} className="flex-1 bg-[var(--border-subtle)] py-3 rounded-2xl text-[9px] font-black text-[var(--text-muted)] uppercase tracking-widest">Redraw</button>
                               <button onClick={handleSaveEdit} className="flex-1 bg-[var(--accent)] text-black py-3 rounded-2xl text-[9px] font-black uppercase tracking-[0.2em]">Commit</button>
                             </div>
                           </div>
                         ) : (
                           <div className="space-y-6">
                             <div className="flex justify-between items-center text-left">
                               <span className="text-[9px] font-black text-[var(--accent)] uppercase tracking-[0.4em] font-mono select-none">F0{idx+1} // {data.shotType}</span>
                               <button onClick={() => handleEditFrame(idx)} className="text-[var(--text-muted)] hover:text-[var(--accent)] transition-colors bg-[var(--border-subtle)] p-2 rounded-lg" aria-label={`Edit Frame ${idx+1}`}>
                                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
                               </button>
                             </div>
                             <p className="text-[var(--text-primary)] text-left font-medium leading-relaxed line-clamp-3 text-base">{data.description}</p>
                             <div className="pt-6 border-t border-[var(--border-subtle)] flex gap-6 text-[9px] text-[var(--text-muted)] font-mono uppercase tracking-[0.1em] select-none">
                               <span className="bg-[var(--border-subtle)] px-2 py-1 rounded">{data.focalLength}</span>
                               <span className="bg-[var(--border-subtle)] px-2 py-1 rounded">{data.cameraMovement}</span>
                             </div>
                           </div>
                         )}
                      </div>
                   </div>
                 );
               })}
             </div>
          </div>
        )}
        <div ref={endOfOutputRef} />
      </div>

      {errorToast && <Toast message={errorToast} onClose={() => setErrorToast(null)} />}

      {/* Monolith Floating Input Console */}
      <div className="absolute bottom-12 left-0 right-0 px-8 z-30 pointer-events-none">
        <div className="max-w-3xl mx-auto pointer-events-auto">
           {/* Attachment Preview (Image or PDF) */}
           {mediaFile && (
             <div className="mb-6 bg-[var(--bg-studio)] border border-[var(--border-subtle)] rounded-[2rem] p-3 w-fit flex items-center gap-4 shadow-[0_20px_40px_rgba(0,0,0,0.4)] animate-slide-up border-b-[var(--accent)]/50">
               {mediaType === 'image' && mediaPreview ? (
                   <img src={mediaPreview} className="w-12 h-12 rounded-xl object-cover" alt="Upload preview" />
               ) : (
                   <div className="w-12 h-12 rounded-xl bg-red-500/10 flex items-center justify-center border border-red-500/20 text-red-500">
                      <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" /></svg>
                   </div>
               )}
               <div className="flex flex-col">
                   <span className="text-[10px] font-bold text-[var(--text-primary)] max-w-[150px] truncate">{mediaFile.name}</span>
                   <span className="text-[9px] text-[var(--text-muted)] uppercase tracking-wider">{mediaType === 'image' ? 'Visual Ref' : 'Script Doc'}</span>
               </div>
               <button onClick={() => {setMediaFile(null); setMediaPreview(null); setMediaType(null);}} className="text-[var(--text-muted)] hover:text-red-500 pr-3 transition-colors ml-2" aria-label="Remove attachment">✕</button>
             </div>
           )}

           <div className="bg-[var(--bg-panel)] backdrop-blur-2xl border border-[var(--border-subtle)] rounded-[2.5rem] shadow-[0_40px_80px_-20px_rgba(0,0,0,0.5)] flex items-end p-2.5 transition-all duration-500 focus-within:border-[var(--accent)]/50 focus-within:shadow-[0_0_25px_var(--shadow-glow)]">
              {canUpload && (
                <button 
                  onClick={() => fileInputRef.current?.click()} 
                  className="p-5 text-[var(--text-muted)] hover:text-[var(--accent)] transition-all duration-300" 
                  title={module.requiresImage ? "Attach Visual Context" : "Upload Script (.txt, .md, .pdf)"}
                  aria-label={module.requiresImage ? "Upload Image" : "Upload Script"}
                >
                  {module.requiresImage ? (
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                  ) : (
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" /></svg>
                  )}
                </button>
              )}
              <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" accept={uploadAccept} />

              <div className="flex-1 relative">
                 <span className="absolute left-5 top-5 text-[var(--accent)] font-mono text-base pointer-events-none select-none">&gt;_</span>
                 <textarea 
                   value={textInput}
                   onChange={(e) => setTextInput(e.target.value)}
                   onKeyDown={handleKeyDown}
                   placeholder={`Ask ${module.title.toUpperCase()}...`}
                   className="w-full bg-transparent text-[var(--text-primary)] placeholder-[var(--text-muted)] text-sm py-5 pl-12 pr-6 outline-none resize-none max-h-48 min-h-[64px] font-mono leading-relaxed"
                   rows={1}
                   style={{ height: 'auto', minHeight: '64px' }}
                   aria-label="Prompt Input"
                 />
              </div>

              <button 
                onClick={() => handleExecute()}
                disabled={loading || (!textInput.trim() && !mediaFile)}
                className={`p-5 m-1 rounded-[1.75rem] transition-all duration-500 shadow-2xl ${
                   textInput.trim() || mediaFile 
                     ? 'bg-[var(--accent)] text-black hover:bg-white active:scale-95 shadow-[var(--accent)]/20' 
                     : 'bg-[var(--bg-studio)] text-[var(--text-muted)] cursor-not-allowed opacity-30'
                }`}
                aria-label={loading ? 'Processing' : 'Initialize Agent'}
              >
                {loading ? (
                    <span className="block w-6 h-6 border-2 border-black/30 border-t-black rounded-full animate-spin"></span>
                ) : (
                    <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
                      <path strokeLinecap="round" strokeLinejoin="round" d="M14 5l7 7m0 0l-7 7m7-7H3" />
                    </svg>
                )}
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

export default ActiveModule;

import { ModuleId } from '../types';
import { SYSTEM_INSTRUCTIONS } from '../constants';

export const getValidApiKey = (): string => {
  const win = window as any;
  const key = win.process?.env?.API_KEY || localStorage.getItem('obscura_api_key');
  if (!key || key.length < 5) {
    throw new Error("Neural Gate Unauthorized. Please enter a valid Gemini API Key.");
  }
  return key;
};

export const fileToGenerativePart = async (file: File): Promise<{ inlineData: { data: string; mimeType: string } }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      const base64Data = base64String.split(',')[1];
      resolve({
        inlineData: {
          data: base64Data,
          mimeType: file.type,
        },
      });
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

export const streamModuleContent = async (
  moduleId: ModuleId,
  textInput: string,
  mediaFile: File | null, // Updated from imageFile to mediaFile to support generic attachments
  onChunk: (text: string) => void,
  signal?: AbortSignal
): Promise<string> => {
  const apiKey = getValidApiKey();
  const systemInstruction = SYSTEM_INSTRUCTIONS[moduleId];
  const modelName = 'gemini-3-pro-preview'; 

  const parts: any[] = [];
  if (mediaFile) {
    const mediaPart = await fileToGenerativePart(mediaFile);
    parts.push(mediaPart);
  }
  if (textInput) {
    parts.push({ text: textInput });
  }

  const payload: any = {
    contents: [{ parts }],
    system_instruction: { parts: [{ text: systemInstruction }] },
    generationConfig: {
      temperature: 0.7,
      topP: 0.95,
      topK: 40,
    }
  };

  if (moduleId === ModuleId.STORYBOARD) {
    payload.generationConfig.responseMimeType = "application/json";
  }

  try {
    const response = await fetch(
      `https://generativelanguage.googleapis.com/v1beta/models/${modelName}:streamGenerateContent?alt=sse&key=${apiKey}`,
      {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
        signal // Pass the abort signal
      }
    );

    if (!response.ok) {
      let errorMessage = "Uplink disrupted.";
      try {
        const err = await response.json();
        errorMessage = err.error?.message || errorMessage;
      } catch (e) {
        errorMessage = `HTTP Error ${response.status}: ${response.statusText}`;
      }
      throw new Error(errorMessage);
    }

    const reader = response.body?.getReader();
    if (!reader) throw new Error("Stream unreachable.");

    const decoder = new TextDecoder();
    let fullText = '';
    let buffer = '';

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      // Buffering logic to handle split chunks
      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split('\n');

      // Keep the last line in the buffer as it might be incomplete
      buffer = lines.pop() || '';

      for (const line of lines) {
        if (line.startsWith('data: ')) {
          try {
            const json = JSON.parse(line.substring(6));
            const text = json.candidates?.[0]?.content?.parts?.[0]?.text;
            if (text) {
              fullText += text;
              onChunk(text);
            }
          } catch (e) {
            // Ignore incomplete or malformed lines
          }
        }
      }
    }

    if (!fullText) throw new Error("Synthesis failed to converge.");
    return fullText;
  } catch (error: any) {
    if (error.name === 'AbortError') {
      throw new Error("Request timed out by operator.");
    }
    console.error("Gemini Service Error:", error);
    throw new Error(error.message || "Neural uplink failure.");
  }
};

export const generateSingleFrame = async (
  description: string,
  shotSpecs: string
): Promise<string> => {
  const apiKey = getValidApiKey();
  const modelName = 'gemini-3-pro-preview';

  const prompt = `Draw a professional storyboard frame in SVG format based on this description: "${description}".
                 Technical Specs: ${shotSpecs}.
                 Style: loose black pencil sketch on white background.
                 Return ONLY the raw SVG string (<svg viewBox="0 0 400 300"...>...</svg>). No markdown.`;

  try {
    const response = await fetch(
      `https://generativelanguage.googleapis.com/v1beta/models/${modelName}:generateContent?key=${apiKey}`,
      {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          contents: [{ parts: [{ text: prompt }] }],
          generationConfig: { temperature: 0.2 }
        }),
      }
    );

    if (!response.ok) {
      let errorMessage = "Network response was not ok";
      try {
        const err = await response.json();
        errorMessage = err.error?.message || errorMessage;
      } catch (e) {
        errorMessage = `HTTP Error ${response.status}: ${response.statusText}`;
      }
      throw new Error(errorMessage);
    }

    const data = await response.json();
    let text = data.candidates?.[0]?.content?.parts?.[0]?.text;

    if (text) {
      text = text.replace(/```svg/g, '').replace(/```/g, '').trim();
    }
    if (!text) throw new Error("SVG synthesis failed.");
    return text;
  } catch (error: any) {
    console.error("Single Frame Generation Error:", error);
    throw new Error(error.message || "Neural redraw failed.");
  }
};

import React, { useState, useRef, useContext, useEffect } from 'react';
import { ModuleDefinition, ModuleId, StoryboardFrame } from '../types';
import { streamModuleContent, generateSingleFrame } from '../services/geminiService';
import { generateCinematicImage } from '../services/bananaProService';
import { ApiKeyContext } from '../contexts/ApiKeyContext';
import MobileHeader from './MobileHeader';
import Toast from './Toast';

interface ActiveModuleProps {
  module: ModuleDefinition;
  history: string[];
  onResultGenerated: (result: string) => void;
  onUpdateHistory?: (result: string) => void;
  onExitModule: () => void;
  onToggleSidebar: () => void;
}

const ActiveModule: React.FC<ActiveModuleProps> = ({ module, history, onResultGenerated, onUpdateHistory, onExitModule, onToggleSidebar }) => {
  const apiKey = useContext(ApiKeyContext);
  const [textInput, setTextInput] = useState('');

  // Media State (Images or PDFs)
  const [mediaFile, setMediaFile] = useState<File | null>(null);
  const [mediaType, setMediaType] = useState<'image' | 'application' | null>(null);
  const [mediaPreview, setMediaPreview] = useState<string | null>(null);

  const [loading, setLoading] = useState(false);
  const [thinkingState, setThinkingState] = useState<'idle' | 'processing' | 'complete'>('idle');
  const [isFadingOut, setIsFadingOut] = useState(false);
  const [timeLeft, setTimeLeft] = useState(0); // Progress timer

  const [exporting, setExporting] = useState(false);
  const [output, setOutput] = useState<string | null>(null);
  const [storyboardData, setStoryboardData] = useState<StoryboardFrame[]>([]);

  const [thinkingStepIndex, setThinkingStepIndex] = useState(0);

  const [editingFrameIndex, setEditingFrameIndex] = useState<number | null>(null);
  const [editedFrameData, setEditedFrameData] = useState<StoryboardFrame | null>(null);
  const [regeneratingIndex, setRegeneratingIndex] = useState<number | null>(null);
  const [generatingImageIndex, setGeneratingImageIndex] = useState<number | null>(null);

  const [errorToast, setErrorToast] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const storyboardRef = useRef<HTMLDivElement>(null);
  const endOfOutputRef = useRef<HTMLDivElement>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    endOfOutputRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [output, storyboardData, thinkingState]);

  useEffect(() => {
    if (history.length > 0) {
      processOutput(history[history.length - 1]);
    } else {
      setOutput(null);
      setStoryboardData([]);
    }
  }, [module.id, history]);

  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (thinkingState === 'processing') {
      setIsFadingOut(false);
      setThinkingStepIndex(0);
      setTimeLeft(45); // Start 45s countdown

      interval = setInterval(() => {
        setThinkingStepIndex(prev => prev < module.steps.length - 1 ? prev + 1 : prev);
        setTimeLeft(prev => Math.max(0, prev - 1));
      }, 1000); // Update every second
    } else if (thinkingState === 'complete') {
        setThinkingStepIndex(module.steps.length - 1);
        const timer = setTimeout(() => {
            setIsFadingOut(true);
            setTimeout(() => {
              setThinkingState('idle');
              setIsFadingOut(false);
            }, 600);
        }, 1500);
        return () => clearTimeout(timer);
    }
    return () => clearInterval(interval);
  }, [thinkingState, module.steps]);

  // Determine if this module supports file uploads (Image OR Script)
  const isScriptModule = module.id === ModuleId.STORYBOARD || module.id === ModuleId.SUBTEXT;
  const canUpload = module.requiresImage || isScriptModule;
  const uploadAccept = module.requiresImage ? "image/*" : ".txt,.md,.fountain,.json,.pdf";

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setErrorToast(null);

    if (module.requiresImage) {
        // Image Mode
        if (!file.type.startsWith('image/')) {
             setErrorToast("This module requires an image file.");
             return;
        }
        setMediaFile(file);
        setMediaType('image');
        const reader = new FileReader();
        reader.onloadend = () => setMediaPreview(reader.result as string);
        reader.readAsDataURL(file);
    } else {
        // Script Mode
        if (file.type === 'application/pdf') {
             setMediaFile(file);
             setMediaType('application');
             setMediaPreview(null);
             setErrorToast("PDF Script attached.");
        } else {
             // Text Mode (txt, md, fountain)
             const validExtensions = ['.txt', '.md', '.fountain', '.json'];
             const isTextType = file.type.startsWith('text/') || validExtensions.some(ext => file.name.toLowerCase().endsWith(ext));

             if (!isTextType) {
                  setErrorToast("Unsupported format. Use .pdf, .txt, .md, or .fountain.");
                  return;
             }

             const reader = new FileReader();
             reader.onload = (event) => {
                 const content = event.target?.result as string;
                 // Inject content directly into the input field for editable text
                 setTextInput(content); 
                 setErrorToast("Script text loaded.");
             };
             reader.onerror = () => setErrorToast("Failed to read file.");
             reader.readAsText(file);
        }
    }

    // Reset input so the same file can be selected again if needed
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const processOutput = (result: string) => {
    if (module.id === ModuleId.STORYBOARD) {
      try {
        const frames = JSON.parse(result);
        setStoryboardData(Array.isArray(frames) ? frames : []);
      } catch (e) {
        if (result.trim().startsWith('[')) {
             setErrorToast("Partial storyboard data received. Try simpler input.");
        }
        setOutput(result);
      }
    } else {
      setOutput(result);
    }
  };

  const handleExecute = async (manualInput?: string) => {
    const inputToUse = manualInput || textInput;
    if (!inputToUse.trim() && !mediaFile) return;

    // Cancel previous request if active
    if (abortControllerRef.current) {
        abortControllerRef.current.abort();
    }

    const controller = new AbortController();
    abortControllerRef.current = controller;

    setLoading(true);
    setThinkingState('processing');
    setStoryboardData([]);
    setOutput('');
    setErrorToast(null);

    // Safety Timeout (Client-side)
    const timeoutId = setTimeout(() => {
        if (abortControllerRef.current === controller) {
            controller.abort();
            setErrorToast("Connection timed out (45s). Network latency high.");
            setLoading(false);
            setThinkingState('idle');
        }
    }, 45000); // 45 Seconds Max

    let buffer = '';
    try {
      const result = await streamModuleContent(
        module.id, 
        inputToUse, 
        mediaFile, // Pass generic media file
        (chunk) => {
            buffer += chunk;
            if (module.id !== ModuleId.STORYBOARD) setOutput(buffer);
        },
        controller.signal
      );

      clearTimeout(timeoutId);
      onResultGenerated(result);
      processOutput(result);
      setTextInput(''); // Only clear input on success
      setMediaFile(null);
      setMediaType(null);
      setMediaPreview(null);
      setThinkingState('complete');
    } catch (err: any) {
      clearTimeout(timeoutId);
      if (err.message === "Request timed out by operator.") {
         setErrorToast("Operation cancelled.");
      } else {
         setErrorToast(err.message || "Neural uplink failure.");
      }
      if (buffer && module.id !== ModuleId.STORYBOARD) setOutput(buffer);
      setThinkingState('idle');
    } finally {
      setLoading(false);
      abortControllerRef.current = null;
    }
  };

  const handleCancel = () => {
    if (abortControllerRef.current) {
        abortControllerRef.current.abort();
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleExecute();
    }
  };

  const handleCopy = () => {
    if (!output) return;
    const tmp = document.createElement("DIV");
    tmp.innerHTML = output;
    const cleanText = tmp.textContent || tmp.innerText || "";
    navigator.clipboard.writeText(cleanText).then(() => {
       // Optional: show copy success toast
    });
  };

  const handleEditFrame = (index: number) => {
    setEditingFrameIndex(index);
    setEditedFrameData({ ...storyboardData[index] });
  };

  const handleSaveEdit = () => {
    if (editingFrameIndex !== null && editedFrameData) {
      const newData = [...storyboardData];
      newData[editingFrameIndex] = editedFrameData;
      setStoryboardData(newData);
      if (onUpdateHistory) onUpdateHistory(JSON.stringify(newData));
      setEditingFrameIndex(null);
    }
  };

  const handleRegenerateFrame = async (index: number) => {
    const frame = editingFrameIndex === index ? editedFrameData! : storyboardData[index];
    setRegeneratingIndex(index);
    try {
      const specs = `${frame.shotType}, ${frame.cameraMovement}, ${frame.composition}`;
      const newSvg = await generateSingleFrame(frame.description, specs);
      const newData = [...storyboardData];
      if (editingFrameIndex === index) setEditedFrameData({ ...frame, svg: newSvg });
      else {
        newData[index] = { ...frame, svg: newSvg };
        setStoryboardData(newData);
        if (onUpdateHistory) onUpdateHistory(JSON.stringify(newData));
      }
    } catch (e) { setErrorToast("Redraw failed. Try again."); } 
    finally { setRegeneratingIndex(null); }
  };

  const handleGenerateRealImage = async (index: number) => {
    const frame = storyboardData[index];
    setGeneratingImageIndex(index);
    try {
      const prompt = `Cinematic shot, ${frame.shotType}. ${frame.description}. Lighting: ${frame.lightingNotes}. Style: ${frame.composition}. Photorealistic 8k.`;
      const base64Image = await generateCinematicImage(prompt, apiKey);
      const newData = [...storyboardData];
      newData[index] = { ...frame, generatedImage: base64Image };
      setStoryboardData(newData);
      if (onUpdateHistory) onUpdateHistory(JSON.stringify(newData));
    } catch (e) { setErrorToast("Gen failed."); }
    finally { setGeneratingImageIndex(null); }
  };

  const handleExportPDF = async () => {
    if (!storyboardRef.current || !window.jspdf) return;
    setExporting(true);
    try {
       const { jsPDF } = window.jspdf;
       const doc = new jsPDF('p', 'mm', 'a4');
       const els = storyboardRef.current.querySelectorAll('.storyboard-frame');
       for (let i = 0; i < els.length; i++) {
         if (i > 0) doc.addPage();
         const canvas = await window.html2canvas(els[i] as HTMLElement, { scale: 2, backgroundColor: '#ffffff' });
         const imgData = canvas.toDataURL('image/jpeg', 0.9);
         doc.addImage(imgData, 'JPEG', 10, 10, 190, 0);
       }
       doc.save(`OBSCURA_${module.id}_Story.pdf`);
    } catch(e) { console.error(e); setErrorToast("Export failed."); }
    finally { setExporting(false); }
  };

  const renderContent = () => {
    if (!output && !storyboardData.length && thinkingState === 'idle') {
       return (
         <div className="absolute inset-0 flex flex-col items-center justify-center animate-fade-in p-10 pointer-events-none">
            <div className="text-[var(--text-primary)] animate-breathe mb-12 transform scale-[4]">
               <svg className="w-24 h-24" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={0.5} d={module.icon} /></svg>
            </div>

            <div className="text-center space-y-4 max-w-md">
               <h3 className="text-3xl font-bold tracking-tight">{module.title}</h3>
               <p className="text-[var(--text-secondary)] text-sm leading-relaxed font-light">{module.description}</p>
            </div>
         </div>
       );
    }

    return (
      <div className="max-w-5xl mx-auto w-full pb-72 pt-16 px-8">
        {thinkingState !== 'idle' && (
           <div className={`mb-16 bg-[var(--bg-panel)] border border-[var(--border-subtle)] backdrop-blur-xl rounded-[2.5rem] p-8 flex items-center gap-8 shadow-2xl transition-all duration-1000 transform ${isFadingOut ? 'opacity-0 -translate-y-12 scale-95 overflow-hidden' : 'opacity-100'}`}>
              <div className="relative w-14 h-14 flex items-center justify-center shrink-0">
                 {thinkingState === 'complete' ? (
                   <div className="text-[var(--accent)] animate-scale-in">
                      <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>
                   </div>
                 ) : (
                   <>
                     <div className="absolute inset-0 border-[3px] border-[var(--accent)]/10 rounded-full"></div>
                     <div className="absolute inset-0 border-[3px] border-[var(--accent)] border-t-transparent rounded-full animate-spin"></div>
                     <div className="text-[9px] font-black text-[var(--accent)] font-mono tracking-tighter">{timeLeft}s</div>
                   </>
                 )}
              </div>
              <div className="flex-1 min-w-0 text-left">
                 <h4 className="text-[9px] font-black text-[var(--accent)] uppercase tracking-[0.4em] mb-1.5 font-mono select-none">
                    {thinkingState === 'complete' ? 'Synthesis Converged' : 'Neural Processing'}
                 </h4>
                 <div className="flex items-center justify-between gap-4">
                   <div className="flex items-center gap-2">
                     <span className="text-xl font-bold truncate tracking-tight">
                        {thinkingState === 'complete' ? 'Success' : `${module.steps[thinkingStepIndex]}`}
                     </span>
                     {thinkingState === 'processing' && <span className="animate-pulse text-[var(--accent)] font-mono text-xl">_</span>}
                   </div>

                   {thinkingState === 'processing' && (
                     <button 
                       onClick={handleCancel}
                       className="px-4 py-2 border border-red-500/30 bg-red-500/10 text-red-500 rounded-xl text-[9px] font-black uppercase tracking-[0.2em] hover:bg-red-500 hover:text-white transition-all"
                     >
                       Abort
                     </button>
                   )}
                 </div>
              </div>
           </div>
        )}

        {output && module.id !== ModuleId.STORYBOARD && (
          <div className="bg-[var(--bg-card)] border border border-[var(--border-subtle)] rounded-[3rem] p-12 shadow-sm animate-slide-up backdrop-blur-[2px] relative group">
             <button 
                onClick={handleCopy}
                className="absolute top-6 right-6 opacity-0 group-hover:opacity-100 transition-opacity p-3 text-[var(--text-muted)] hover:text-[var(--accent)] bg-[var(--bg-studio)] rounded-xl border border-[var(--border-subtle)]"
                aria-label="Copy output to clipboard"
                title="Copy to Clipboard"
             >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
             </button>
             <div 
               className="prose prose-invert max-w-none text-[var(--text-secondary)] font-inter text-sm leading-[1.8] marker:text-[var(--accent)]"
               dangerouslySetInnerHTML={{ __html: output }}
             />
          </div>
        )}

        {storyboardData.length > 0 && (
          <div ref={storyboardRef} className="space-y-16 animate-slide-up">
             <div className="flex justify-between items-end border-b border-[var(--border-subtle)] pb-8">
                <div>
                  <h3 className="text-4xl font-bold tracking-tighter">Visual Archive</h3>
                  <p className="text-[var(--text-muted)] text-sm mt-2 font-light tracking-wide">Analysis Log // Sequence 01</p>
                </div>
                <button onClick={handleExportPDF} disabled={exporting} className="bg-[var(--text-primary)] text-[var(--bg-studio)] px-8 py-3 rounded-[1.25rem] text-[9px] font-black uppercase tracking-[0.2em] hover:bg-[var(--accent)] hover:text-black transition-all active:scale-95 shadow-xl" aria-label="Export PDF Dossier">
                  {exporting ? 'Processing' : 'Export Dossier'}
                </button>
             </div>

             <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
               {storyboardData.map((frame, idx) => {
                 const isEditing = editingFrameIndex === idx;
                 const data = isEditing ? editedFrameData! : frame;
                 const isBusy = regeneratingIndex === idx || generatingImageIndex === idx;

                 return (
                   <div key={idx} className="storyboard-frame bg-[var(--bg-card)] border border-[var(--border-subtle)] rounded-[2.5rem] overflow-hidden group hover:border-[var(--accent)]/30 transition-all duration-700">
                      <div className="aspect-video bg-white relative flex items-center justify-center overflow-hidden">
                         {isBusy && (
                           <div className="absolute inset-0 bg-white/95 z-20 flex items-center justify-center">
                              <div className="w-10 h-10 border-4 border-black border-t-transparent rounded-full animate-spin"></div>
                           </div>
                         )}
                         {data.generatedImage ? (
                           <img src={data.generatedImage} alt={`Frame ${idx+1}: ${data.description}`} className="w-full h-full object-cover" />
                         ) : (
                           <div className="p-12 w-full h-full opacity-90 scale-105 group-hover:scale-100 transition-transform duration-1000" dangerouslySetInnerHTML={{ __html: data.svg }} />
                         )}
                         <div className="absolute top-6 right-6 flex gap-3 opacity-0 group-hover:opacity-100 transition-all translate-y-3 group-hover:translate-y-0">
                            {!data.generatedImage && (
                              <button onClick={() => handleGenerateRealImage(idx)} className="bg-black text-white px-4 py-2 rounded-xl text-[8px] font-black uppercase tracking-widest hover:bg-[var(--accent)] hover:text-black transition-all shadow-2xl" aria-label="Render High-Fidelity Image">
                                 Render High-Fi
                              </button>
                            )}
                         </div>
                      </div>

                      <div className="p-10 text-sm">
                         {isEditing ? (
                           <div className="space-y-6">
                             <textarea className="w-full bg-[var(--bg-studio)] text-[var(--text-primary)] p-5 rounded-3xl text-xs border border-[var(--border-subtle)] outline-none focus:border-[var(--accent)]/50 transition-colors font-mono" rows={3} value={data.description} onChange={e => setEditedFrameData({...data, description: e.target.value})} />
                             <div className="flex gap-3">
                               <button onClick={() => handleRegenerateFrame(idx)} className="flex-1 bg-[var(--border-subtle)] py-3 rounded-2xl text-[9px] font-black text-[var(--text-muted)] uppercase tracking-widest">Redraw</button>
                               <button onClick={handleSaveEdit} className="flex-1 bg-[var(--accent)] text-black py-3 rounded-2xl text-[9px] font-black uppercase tracking-[0.2em]">Commit</button>
                             </div>
                           </div>
                         ) : (
                           <div className="space-y-6">
                             <div className="flex justify-between items-center text-left">
                               <span className="text-[9px] font-black text-[var(--accent)] uppercase tracking-[0.4em] font-mono select-none">F0{idx+1} // {data.shotType}</span>
                               <button onClick={() => handleEditFrame(idx)} className="text-[var(--text-muted)] hover:text-[var(--accent)] transition-colors bg-[var(--border-subtle)] p-2 rounded-lg" aria-label={`Edit Frame ${idx+1}`}>
                                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
                               </button>
                             </div>
                             <p className="text-[var(--text-primary)] text-left font-medium leading-relaxed line-clamp-3 text-base">{data.description}</p>
                             <div className="pt-6 border-t border-[var(--border-subtle)] flex gap-6 text-[9px] text-[var(--text-muted)] font-mono uppercase tracking-[0.1em] select-none">
                               <span className="bg-[var(--border-subtle)] px-2 py-1 rounded">{data.focalLength}</span>
                               <span className="bg-[var(--border-subtle)] px-2 py-1 rounded">{data.cameraMovement}</span>
                             </div>
                           </div>
                         )}
                      </div>
                   </div>
                 );
               })}
             </div>
          </div>
        )}
        <div ref={endOfOutputRef} />
      </div>
    );
  };

  return (
    <>
      {renderContent()}

      {errorToast && <Toast message={errorToast} onClose={() => setErrorToast(null)} />}

      {/* Monolith Floating Input Console */}
      <div className="absolute bottom-12 left-0 right-0 px-8 z-30 pointer-events-none">
        <div className="max-w-3xl mx-auto pointer-events-auto">
           {/* Attachment Preview (Image or PDF) */}
           {mediaFile && (
             <div className="mb-6 bg-[var(--bg-studio)] border border-[var(--border-subtle)] rounded-[2rem] p-3 w-fit flex items-center gap-4 shadow-[0_20px_40px_rgba(0,0,0,0.4)] animate-slide-up border-b-[var(--accent)]/50">
               {mediaType === 'image' && mediaPreview ? (
                   <img src={mediaPreview} className="w-12 h-12 rounded-xl object-cover" alt="Upload preview" />
               ) : (
                   <div className="w-12 h-12 rounded-xl bg-red-500/10 flex items-center justify-center border border-red-500/20 text-red-500">
                      <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" /></svg>
                   </div>
               )}
               <div className="flex flex-col">
                   <span className="text-[10px] font-bold text-[var(--text-primary)] max-w-[150px] truncate">{mediaFile.name}</span>
                   <span className="text-[9px] text-[var(--text-muted)] uppercase tracking-wider">{mediaType === 'image' ? 'Visual Ref' : 'Script Doc'}</span>
               </div>
               <button onClick={() => {setMediaFile(null); setMediaPreview(null); setMediaType(null);}} className="text-[var(--text-muted)] hover:text-red-500 pr-3 transition-colors ml-2" aria-label="Remove attachment">✕</button>
             </div>
           )}

           <div className="bg-[var(--bg-panel)] backdrop-blur-2xl border border-[var(--border-subtle)] rounded-[2.5rem] shadow-[0_40px_80px_-20px_rgba(0,0,0,0.5)] flex items-end p-2.5 transition-all duration-500 focus-within:border-[var(--accent)]/50 focus-within:shadow-[0_0_25px_var(--shadow-glow)]">
              {canUpload && (
                <button 
                  onClick={() => fileInputRef.current?.click()} 
                  className="p-5 text-[var(--text-muted)] hover:text-[var(--accent)] transition-all duration-300" 
                  title={module.requiresImage ? "Attach Visual Context" : "Upload Script (.txt, .md, .pdf)"}
                  aria-label={module.requiresImage ? "Upload Image" : "Upload Script"}
                >
                  {module.requiresImage ? (
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                  ) : (
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" /></svg>
                  )}
                </button>
              )}
              <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" accept={uploadAccept} />

              <div className="flex-1 relative">
                 <span className="absolute left-5 top-5 text-[var(--accent)] font-mono text-base pointer-events-none select-none">&gt;_</span>
                 <textarea 
                   value={textInput}
                   onChange={(e) => setTextInput(e.target.value)}
                   onKeyDown={handleKeyDown}
                   placeholder={`Ask ${module.title.toUpperCase()}...`}
                   className="w-full bg-transparent text-[var(--text-primary)] placeholder-[var(--text-muted)] text-sm py-5 pl-12 pr-6 outline-none resize-none max-h-48 min-h-[64px] font-mono leading-relaxed"
                   rows={1}
                   style={{ height: 'auto', minHeight: '64px' }}
                   aria-label="Prompt Input"
                 />
              </div>

              <button 
                onClick={() => handleExecute()}
                disabled={loading || (!textInput.trim() && !mediaFile)}
                className={`p-5 m-1 rounded-[1.75rem] transition-all duration-500 shadow-2xl ${
                   textInput.trim() || mediaFile 
                     ? 'bg-[var(--accent)] text-black hover:bg-white active:scale-95 shadow-[var(--accent)]/20' 
                     : 'bg-[var(--bg-studio)] text-[var(--text-muted)] cursor-not-allowed opacity-30'
                }`}
                aria-label={loading ? 'Processing' : 'Initialize Agent'}
              >
                {loading ? (
                    <span className="block w-6 h-6 border-2 border-black/30 border-t-black rounded-full animate-spin"></span>
                ) : (
                    <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
                      <path strokeLinecap="round" strokeLinejoin="round" d="M14 5l7 7m0 0l-7 7m7-7H3" />
                    </svg>
                )}
              </button>
           </div>
        </div>
      </div>
    </>
  );
};

export default ActiveModule;

import React, { useState, useEffect, useCallback, ErrorInfo, ReactNode } from 'react';
import { AppState, UserProfile } from './types';
import Landing from './components/Landing';
import Dashboard from './components/Dashboard';
import Gatekeeper from './components/Gatekeeper';
import FlashlightCursor from './components/FlashlightCursor';
import { ApiKeyContext } from './contexts/ApiKeyContext';

interface ErrorBoundaryProps {
  children?: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: any;
}

// Error Boundary to prevent "Black Screen of Death"
class ErrorBoundary extends React.Component<ErrorBoundaryProps, ErrorBoundaryState> {
  public state: ErrorBoundaryState = { hasError: false, error: null };

  constructor(props: ErrorBoundaryProps) {
    super(props);
  }

  static getDerivedStateFromError(error: any): ErrorBoundaryState {
    return { hasError: true, error };
  }

  componentDidCatch(error: any, errorInfo: ErrorInfo) {
    console.error("Critical System Failure:", error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen bg-black text-red-500 flex flex-col items-center justify-center p-8 font-mono text-xs z-50 relative">
          <div className="max-w-xl w-full">
            <h1 className="text-xl mb-4 font-bold tracking-widest border-b border-red-900 pb-4">SYSTEM_FAILURE_DETECTED</h1>
            <p className="mb-4 text-zinc-400">The neural link encountered a critical exception.</p>
            <pre className="bg-[#111] p-6 rounded-xl overflow-auto border border-red-900/50 mb-8 font-mono text-[10px] leading-relaxed">
              {this.state.error?.toString()}
            </pre>
            <button 
              onClick={() => {
                localStorage.clear(); 
                window.location.reload();
              }}
              className="w-full border border-red-500/50 text-red-500 px-6 py-4 hover:bg-red-900/20 rounded-xl transition-all uppercase tracking-[0.2em] font-bold"
            >
              Initiate Hard Reset
            </button>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.LANDING);
  const [user, setUser] = useState<UserProfile | null>(null);

  // Use a safer initializer for the runtime key
  const [runtimeKey, setRuntimeKey] = useState<string>(() => {
    try {
      const win = window as any;
      const envKey = win.process?.env?.API_KEY;
      const storedKey = localStorage.getItem('obscura_api_key');
      return envKey || storedKey || '';
    } catch {
      return '';
    }
  });

  // Sync state on mount and handle auto-login
  useEffect(() => {
    const storedUser = localStorage.getItem('obscura_user');
    if (storedUser) {
      try {
        const parsedUser = JSON.parse(storedUser);
        setUser(parsedUser);

        const win = window as any;
        const key = win.process?.env?.API_KEY || localStorage.getItem('obscura_api_key') || '';

        if (key && key.length > 5) {
          setAppState(AppState.DASHBOARD);
        } else {
          setAppState(AppState.GATEKEEPER);
        }
      } catch (e) {
        console.error("Auth hydration failure", e);
        localStorage.removeItem('obscura_user');
        setAppState(AppState.LANDING);
      }
    }
  }, []);

  const handleSignIn = useCallback((userProfile: UserProfile) => {
    localStorage.setItem('obscura_user', JSON.stringify(userProfile));
    setUser(userProfile);

    const win = window as any;
    const currentKey = win.process?.env?.API_KEY || localStorage.getItem('obscura_api_key') || '';

    if (!currentKey || currentKey.length < 5) {
      setAppState(AppState.GATEKEEPER);
    } else {
      setRuntimeKey(currentKey);
      setAppState(AppState.DASHBOARD);
    }
  }, []);

  const handleGatePassed = useCallback((key?: string) => {
    if (key) {
      setRuntimeKey(key);
      const win = window as any;
      if (!win.process) win.process = { env: {} };
      win.process.env.API_KEY = key;
      localStorage.setItem('obscura_api_key', key);
    }
    setAppState(AppState.DASHBOARD);
  }, []);

  const handleLogout = useCallback(() => {
    localStorage.removeItem('obscura_user');
    setUser(null);
    setAppState(AppState.LANDING);
    window.scrollTo(0, 0);
  }, []);

  // Determine what to render based on state
  const renderView = () => {
    if (appState === AppState.DASHBOARD && user) {
      return <Dashboard user={user} onLogout={handleLogout} />;
    }

    if (appState === AppState.GATEKEEPER) {
      return <Gatekeeper onSuccess={handleGatePassed} />;
    }

    // Default fallback is always Landing
    return <Landing onSignIn={handleSignIn} />;
  };

  return (
    <ErrorBoundary>
      <ApiKeyContext.Provider value={runtimeKey}>
        <FlashlightCursor />
        {/* Main Content Container with High Z-Index to sit ABOVE the film grain */}
        <div className="min-h-screen bg-[#050505] relative z-20">
          {renderView()}
        </div>
      </ApiKeyContext.Provider>
    </ErrorBoundary>
  );
};

export default App;

import React, { useState, useRef, useContext, useEffect } from 'react';
import { ModuleDefinition, ModuleId, StoryboardFrame } from '../types';
import { streamModuleContent, generateSingleFrame } from '../services/geminiService';
import { generateCinematicImage } from '../services/bananaProService';
import { ApiKeyContext } from '../contexts/ApiKeyContext';
import MobileHeader from './MobileHeader';
import Toast from './Toast';

interface ActiveModuleProps {
  module: ModuleDefinition;
  history: string[];
  onResultGenerated: (result: string) => void;
  onUpdateHistory?: (result: string) => void;
  onExitModule: () => void;
  onToggleSidebar: () => void;
}

const MAX_FILE_SIZE_MB = 10;
const MAX_FILE_BYTES = MAX_FILE_SIZE_MB * 1024 * 1024;

const ActiveModule: React.FC<ActiveModuleProps> = ({ module, history, onResultGenerated, onUpdateHistory, onExitModule, onToggleSidebar }) => {
  const apiKey = useContext(ApiKeyContext);
  const [textInput, setTextInput] = useState('');

  // Media State (Images or PDFs)
  const [mediaFile, setMediaFile] = useState<File | null>(null);
  const [mediaType, setMediaType] = useState<'image' | 'application' | null>(null);
  const [mediaPreview, setMediaPreview] = useState<string | null>(null);

  const [loading, setLoading] = useState(false);
  const [thinkingState, setThinkingState] = useState<'idle' | 'processing' | 'complete'>('idle');
  const [isFadingOut, setIsFadingOut] = useState(false);
  const [timeLeft, setTimeLeft] = useState(0); // Progress timer

  const [exporting, setExporting] = useState(false);
  const [output, setOutput] = useState<string | null>(null);
  const [storyboardData, setStoryboardData] = useState<StoryboardFrame[]>([]);

  const [thinkingStepIndex, setThinkingStepIndex] = useState(0);

  const [editingFrameIndex, setEditingFrameIndex] = useState<number | null>(null);
  const [editedFrameData, setEditedFrameData] = useState<StoryboardFrame | null>(null);
  const [regeneratingIndex, setRegeneratingIndex] = useState<number | null>(null);
  const [generatingImageIndex, setGeneratingImageIndex] = useState<number | null>(null);

  const [errorToast, setErrorToast] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const storyboardRef = useRef<HTMLDivElement>(null);
  const endOfOutputRef = useRef<HTMLDivElement>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    endOfOutputRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [output, storyboardData, thinkingState]);

  useEffect(() => {
    if (history.length > 0) {
      processOutput(history[history.length - 1]);
    } else {
      setOutput(null);
      setStoryboardData([]);
    }
  }, [module.id, history]);

  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (thinkingState === 'processing') {
      setIsFadingOut(false);
      setThinkingStepIndex(0);
      setTimeLeft(45); // Start 45s countdown

      interval = setInterval(() => {
        setThinkingStepIndex(prev => prev < module.steps.length - 1 ? prev + 1 : prev);
        setTimeLeft(prev => Math.max(0, prev - 1));
      }, 1000); // Update every second
    } else if (thinkingState === 'complete') {
        setThinkingStepIndex(module.steps.length - 1);
        const timer = setTimeout(() => {
            setIsFadingOut(true);
            setTimeout(() => {
              setThinkingState('idle');
              setIsFadingOut(false);
            }, 600);
        }, 1500);
        return () => clearTimeout(timer);
    }
    return () => clearInterval(interval);
  }, [thinkingState, module.steps]);

  // Determine if this module supports file uploads (Image OR Script)
  const isScriptModule = module.id === ModuleId.STORYBOARD || module.id === ModuleId.SUBTEXT;
  const canUpload = module.requiresImage || isScriptModule;
  const uploadAccept = module.requiresImage ? "image/*" : ".txt,.md,.fountain,.json,.pdf";

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setErrorToast(null);

    // 1. File Size Guard
    if (file.size > MAX_FILE_BYTES) {
        setErrorToast(`File too large (${(file.size / 1024 / 1024).toFixed(1)}MB). Limit is ${MAX_FILE_SIZE_MB}MB.`);
        if (fileInputRef.current) fileInputRef.current.value = '';
        return;
    }

    if (module.requiresImage) {
        // Image Mode
        if (!file.type.startsWith('image/')) {
             setErrorToast("This module requires an image file.");
             return;
        }
        setMediaFile(file);
        setMediaType('image');
        const reader = new FileReader();
        reader.onloadend = () => setMediaPreview(reader.result as string);
        reader.readAsDataURL(file);
    } else {
        // Script Mode
        if (file.type === 'application/pdf') {
             setMediaFile(file);
             setMediaType('application');
             setMediaPreview(null);
             setErrorToast("PDF Script attached.");
        } else {
             // Text Mode (txt, md, fountain)
             const validExtensions = ['.txt', '.md', '.fountain', '.json'];
             const isTextType = file.type.startsWith('text/') || validExtensions.some(ext => file.name.toLowerCase().endsWith(ext));

             if (!isTextType) {
                  setErrorToast("Unsupported format. Use .pdf, .txt, .md, or .fountain.");
                  return;
             }

             const reader = new FileReader();
             reader.onload = (event) => {
                 const content = event.target?.result as string;
                 // Inject content directly into the input field for editable text
                 setTextInput(content); 
                 setErrorToast("Script text loaded.");
             };
             reader.onerror = () => setErrorToast("Failed to read file.");
             reader.readAsText(file);
        }
    }

    // Reset input so the same file can be selected again if needed
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const processOutput = (result: string) => {
    if (module.id === ModuleId.STORYBOARD) {
      try {
        // 2. Robust JSON Sanitization
        // Remove Markdown code blocks if present (e.g. ```json ... ```)
        let cleanResult = result.trim();
        if (cleanResult.startsWith('```')) {
            cleanResult = cleanResult.replace(/^```(json)?/, '').replace(/```$/, '');
        }

        const frames = JSON.parse(cleanResult);
        setStoryboardData(Array.isArray(frames) ? frames : []);
      } catch (e) {
        console.warn("JSON Parse Error", e);
        if (result.trim().startsWith('[')) {
             setErrorToast("Partial storyboard data received. Try simpler input.");
        } else {
             // If completely failed to parse JSON, show raw text output as fallback
             setOutput(result);
        }
      }
    } else {
      setOutput(result);
    }
  };

  const handleExecute = async (manualInput?: string) => {
    const inputToUse = manualInput || textInput;
    if (!inputToUse.trim() && !mediaFile) return;

    // Cancel previous request if active
    if (abortControllerRef.current) {
        abortControllerRef.current.abort();
    }

    const controller = new AbortController();
    abortControllerRef.current = controller;

    setLoading(true);
    setThinkingState('processing');
    setStoryboardData([]);
    setOutput('');
    setErrorToast(null);

    // Safety Timeout (Client-side)
    const timeoutId = setTimeout(() => {
        if (abortControllerRef.current === controller) {
            controller.abort();
            setErrorToast("Connection timed out (45s). Network latency high.");
            setLoading(false);
            setThinkingState('idle');
        }
    }, 45000); // 45 Seconds Max

    let buffer = '';
    try {
      const result = await streamModuleContent(
        module.id, 
        inputToUse, 
        mediaFile, // Pass generic media file
        (chunk) => {
            buffer += chunk;
            if (module.id !== ModuleId.STORYBOARD) setOutput(buffer);
        },
        controller.signal
      );

      clearTimeout(timeoutId);
      onResultGenerated(result);
      processOutput(result);
      setTextInput(''); // Only clear input on success
      setMediaFile(null);
      setMediaType(null);
      setMediaPreview(null);
      setThinkingState('complete');
    } catch (err: any) {
      clearTimeout(timeoutId);
      if (err.message === "Request timed out by operator.") {
         setErrorToast("Operation cancelled.");
      } else {
         setErrorToast(err.message || "Neural uplink failure.");
      }
      if (buffer && module.id !== ModuleId.STORYBOARD) setOutput(buffer);
      setThinkingState('idle');
    } finally {
      setLoading(false);
      abortControllerRef.current = null;
    }
  };

  const handleCancel = () => {
    if (abortControllerRef.current) {
        abortControllerRef.current.abort();
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleExecute();
    }
  };

  const handleCopy = () => {
    if (!output) return;
    const tmp = document.createElement("DIV");
    tmp.innerHTML = output;
    const cleanText = tmp.textContent || tmp.innerText || "";
    navigator.clipboard.writeText(cleanText).then(() => {
       // Optional: show copy success toast
    });
  };

  const handleEditFrame = (index: number) => {
    setEditingFrameIndex(index);
    setEditedFrameData({ ...storyboardData[index] });
  };

  const handleSaveEdit = () => {
    if (editingFrameIndex !== null && editedFrameData) {
      const newData = [...storyboardData];
      newData[editingFrameIndex] = editedFrameData;
      setStoryboardData(newData);
      if (onUpdateHistory) onUpdateHistory(JSON.stringify(newData));
      setEditingFrameIndex(null);
    }
  };

  const handleRegenerateFrame = async (index: number) => {
    const frame = editingFrameIndex === index ? editedFrameData! : storyboardData[index];
    setRegeneratingIndex(index);
    try {
      const specs = `${frame.shotType}, ${frame.cameraMovement}, ${frame.composition}`;
      const newSvg = await generateSingleFrame(frame.description, specs);
      const newData = [...storyboardData];
      if (editingFrameIndex === index) setEditedFrameData({ ...frame, svg: newSvg });
      else {
        newData[index] = { ...frame, svg: newSvg };
        setStoryboardData(newData);
        if (onUpdateHistory) onUpdateHistory(JSON.stringify(newData));
      }
    } catch (e) { setErrorToast("Redraw failed. Try again."); } 
    finally { setRegeneratingIndex(null); }
  };

  const handleGenerateRealImage = async (index: number) => {
    const frame = storyboardData[index];
    setGeneratingImageIndex(index);
    try {
      const prompt = `Cinematic shot, ${frame.shotType}. ${frame.description}. Lighting: ${frame.lightingNotes}. Style: ${frame.composition}. Photorealistic 8k.`;
      const base64Image = await generateCinematicImage(prompt, apiKey);
      const newData = [...storyboardData];
      newData[index] = { ...frame, generatedImage: base64Image };
      setStoryboardData(newData);
      if (onUpdateHistory) onUpdateHistory(JSON.stringify(newData));
    } catch (e) { setErrorToast("Gen failed."); }
    finally { setGeneratingImageIndex(null); }
  };

  const handleExportPDF = async () => {
    if (!storyboardRef.current || !window.jspdf) return;
    setExporting(true);
    try {
       const { jsPDF } = window.jspdf;
       const doc = new jsPDF('p', 'mm', 'a4');
       const els = storyboardRef.current.querySelectorAll('.storyboard-frame');
       for (let i = 0; i < els.length; i++) {
         if (i > 0) doc.addPage();
         const canvas = await window.html2canvas(els[i] as HTMLElement, { scale: 2, backgroundColor: '#ffffff' });
         const imgData = canvas.toDataURL('image/jpeg', 0.9);
         doc.addImage(imgData, 'JPEG', 10, 10, 190, 0);
       }
       doc.save(`OBSCURA_${module.id}_Story.pdf`);
    } catch(e) { console.error(e); setErrorToast("Export failed."); }
    finally { setExporting(false); }
  };

  const renderContent = () => {
    if (!output && !storyboardData.length && thinkingState === 'idle') {
       return (
         <div className="absolute inset-0 flex flex-col items-center justify-center animate-fade-in p-10 pointer-events-none">
            <div className="text-[var(--text-primary)] animate-breathe mb-12 transform scale-[4]">
               <svg className="w-24 h-24" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={0.5} d={module.icon} /></svg>
            </div>

            <div className="text-center space-y-4 max-w-md">
