import React, { useEffect, useState } from 'react';

interface ToastProps {
  message: string;
  type?: 'error' | 'success' | 'info';
  onClose: () => void;
  duration?: number;
}

const Toast: React.FC<ToastProps> = ({ message, type = 'error', onClose, duration = 5000 }) => {
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    setIsVisible(true);
    const timer = setTimeout(() => {
      setIsVisible(false);
      setTimeout(onClose, 300); // Wait for fade out
    }, duration);
    return () => clearTimeout(timer);
  }, [duration, onClose]);

  const bgColors = {
    error: 'bg-red-500/10 border-red-500 text-red-500',
    success: 'bg-green-500/10 border-green-500 text-green-500',
    info: 'bg-[var(--accent)]/10 border-[var(--accent)] text-[var(--accent)]'
  };

  return (
    <div className={`fixed bottom-8 left-1/2 -translate-x-1/2 z-[100] transition-all duration-300 transform w-full max-w-lg px-6 pointer-events-none ${isVisible ? 'translate-y-0 opacity-100' : 'translate-y-4 opacity-0'}`}>
      <div className={`backdrop-blur-xl border px-6 py-4 rounded-2xl shadow-[0_0_30px_rgba(0,0,0,0.5)] flex items-start gap-4 ${bgColors[type]} pointer-events-auto`}>
        <div className="flex flex-col flex-1 min-w-0">
           <span className="text-[10px] font-black uppercase tracking-[0.2em] mb-1 opacity-70">
             {type === 'error' ? 'System Exception' : type === 'success' ? 'Operation Complete' : 'System Notice'}
           </span>
           <span className="font-mono text-xs font-bold break-words leading-relaxed">{message}</span>
        </div>
        <button onClick={() => setIsVisible(false)} className="opacity-50 hover:opacity-100 transition-opacity p-1 shrink-0 mt-1">
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
        </button>
      </div>
    </div>
  );
};

export default Toast;

import { GoogleGenAI } from "@google/genai";
import { ModuleId } from '../types';
import { SYSTEM_INSTRUCTIONS } from '../constants';

export const getValidApiKey = (): string => {
  const win = window as any;
  const key = win.process?.env?.API_KEY || localStorage.getItem('obscura_api_key');
  if (!key || key.length < 5) {
    throw new Error("Neural Gate Unauthorized. Please enter a valid Gemini API Key.");
  }
  return key;
};

// PRODUCTION FIX: Convert ugly API errors into user-friendly status messages
const sanitizeError = (error: any): string => {
  const msg = error.message || error.toString();

  if (msg.includes('QuotaFailure') || msg.includes('429') || msg.includes('quota') || msg.includes('resource exhausted')) {
    return "System Capacity Reached: Rate limit exceeded. Please wait 60 seconds before retrying.";
  }

  if (msg.includes('503') || msg.includes('overloaded')) {
    return "System Overload: Neural servers are currently busy. Try again shortly.";
  }

  if (msg.includes('SAFETY') || msg.includes('blocked')) {
    return "Safety Protocol: Content flagged by safety filters.";
  }

  // If it's a huge raw JSON dump (like in your screenshot), return a generic error
  if (msg.includes('{') && msg.length > 100) {
      return "Neural Uplink Failure: Connection refused by remote host.";
  }

  return msg;
};

export const fileToGenerativePart = async (file: File): Promise<{ inlineData: { data: string; mimeType: string } }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      const base64Data = base64String.split(',')[1];
      resolve({
        inlineData: {
          data: base64Data,
          mimeType: file.type,
        },
      });
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

export const streamModuleContent = async (
  moduleId: ModuleId,
  textInput: string,
  mediaFile: File | null,
  onChunk: (text: string) => void,
  signal?: AbortSignal
): Promise<string> => {
  const apiKey = getValidApiKey();
  const ai = new GoogleGenAI({ apiKey });
  const systemInstruction = SYSTEM_INSTRUCTIONS[moduleId];
  const modelName = 'gemini-3-pro-preview'; 

  const parts: any[] = [];
  if (mediaFile) {
    const mediaPart = await fileToGenerativePart(mediaFile);
    parts.push(mediaPart);
  }
  if (textInput) {
    parts.push({ text: textInput });
  }

  const config: any = {
    systemInstruction,
    temperature: 0.7,
    topP: 0.95,
    topK: 40,
  };

  if (moduleId === ModuleId.STORYBOARD) {
    config.responseMimeType = "application/json";
  }

  try {
    const result = await ai.models.generateContentStream({
      model: modelName,
      contents: { parts },
      config: config,
    });

    let fullText = '';

    for await (const chunk of result) {
      if (signal?.aborted) {
        throw new Error("Request timed out by operator.");
      }

      const text = chunk.text;
      if (text) {
        fullText += text;
        onChunk(text);
      }
    }

    if (!fullText) throw new Error("Synthesis failed to converge.");
    return fullText;
  } catch (error: any) {
    if (signal?.aborted || error.message === "Request timed out by operator.") {
      throw new Error("Request timed out by operator.");
    }
    console.error("Gemini Service Error:", error);
    // Apply sanitization before throwing back to UI
    throw new Error(sanitizeError(error));
  }
};

export const generateSingleFrame = async (
  description: string,
  shotSpecs: string
): Promise<string> => {
  const apiKey = getValidApiKey();
  const ai = new GoogleGenAI({ apiKey });
  const modelName = 'gemini-3-pro-image-preview'; 

  const prompt = `Create a loose, atmospheric storyboard sketch. 
                 Style: Charcoal drawing on white paper, rough pencil lines, black and white only. 
                 Scene Description: ${description}. 
                 Camera/Composition: ${shotSpecs}.
                 Do not add text to the image. Focus on lighting, blocking, and composition.`;

  try {
    if (window.aistudio) {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        if (!hasKey) {
            await window.aistudio.openSelectKey();
        }
    }

    const response = await ai.models.generateContent({
        model: modelName,
        contents: { parts: [{ text: prompt }] },
        config: { 
            imageConfig: {
                aspectRatio: "16:9",
                imageSize: "1K"
            }
        }
    });

    const parts = response.candidates?.[0]?.content?.parts;

    if (parts) {
      for (const part of parts) {
        if (part.inlineData) {
          const base64Data = part.inlineData.data;
          const mimeType = part.inlineData.mimeType || 'image/png';
          return `data:${mimeType};base64,${base64Data}`;
        }
      }
    }
    throw new Error("No sketch data generated.");
  } catch (error: any) {
    console.error("Sketch Generation Error:", error);
    throw new Error(sanitizeError(error));
  }
};

