// PRODUCTION FIX: Prevent "QuotaExceededError" from crashing the entire app
const safeSetLocalStorage = (key: string, value: string) => {
  try {
    localStorage.setItem(key, value);
  } catch (e: any) {
    if (e.name === 'QuotaExceededError' || e.code === 22) {
      console.warn("Storage Safeguard: Local history quota exceeded. Data saved to session memory only.");
      // In a full production app, you would show a toast warning here.
    } else {
      console.error("Storage Error:", e);
    }
  }
};

